@app.before_request
def restrict_receta_only_user():
    """Usuario temporal vhornac: solo Receta (y logout/static)."""
    from database import is_receta_only_user
    if not current_user.is_authenticated:
        return None
    if not is_receta_only_user():
        return None
    ep = request.endpoint
    if ep in (None, 'static', 'receta_page', 'api_receta_generar_pdf', 'logout', 'login'):
        return None
    if request.path.startswith('/static/'):
        return None
    if request.path.startswith('/api/receta'):
        return None
    return redirect(url_for('receta_page'))


def ensure_user_session():
    """Asegura que company y person estén en sesión (admins EMPWEB pueden no tener person)."""
    if session.get('web_session_loaded'):
        return {'company': session.get('company'), 'person': session.get('person')}

    info = get_datos_usuario_web(current_user.id)
    if info:
        session['company'] = info.get('company') or ''
        session['person'] = info.get('person') or ''
        session['web_session_loaded'] = True
        if info.get('web_user_no_employee'):
            session['web_user_no_employee'] = True
        return info

    # Evita reintentar en cada request si no hay datos
    session.setdefault('company', '')
    session.setdefault('person', '')
    session['web_session_loaded'] = True
    return {'company': session.get('company'), 'person': session.get('person')}


@app.template_filter('importe')
def format_importe(value):
    try:
        return '{:,.2f}'.format(float(value or 0))
    except Exception:
        return '0.00'


@app.template_filter('pct')
def format_pct(value):
    try:
        return '{:.2f} %'.format(float(value or 0))
    except Exception:
        return '0.00 %'


@app.template_filter('fecha')
def fecha_filter(value):
    if not value:
        return ''
    if isinstance(value, datetime):
        return value.strftime('%d/%m/%Y')
    if isinstance(value, date):
        return value.strftime('%d/%m/%Y')
    s = str(value).strip()
    if not s:
        return ''
    try:
        if len(s) >= 10 and s[4] == '-' and s[7] == '-':
            return datetime.strptime(s[:10], '%Y-%m-%d').strftime('%d/%m/%Y')
    except Exception:
        pass
    return s


@app.template_filter('dias')
def format_dias(value):
    try:
        v = float(value or 0)
        if abs(v - round(v)) < 0.00005:
            return '{:,.0f}'.format(v)
        return '{:,.2f}'.format(v)
    except Exception:
        return '0'


@app.context_processor
def inject_now():
    from database import get_active_database, is_receta_only_user
    from web_access import session_can_menu

    es_vhornac = bool(is_receta_only_user()) if current_user.is_authenticated else False

    def can_menu(code):
        if not current_user.is_authenticated:
            return False
        return session_can_menu(session, code)

    return {
        'now': datetime.now(),
        'sql_database': get_active_database(),
        'receta_only': es_vhornac,
        'mostrar_menu_receta': es_vhornac,
        'web_admin': bool(session.get('web_admin')) if current_user.is_authenticated else False,
        'web_access_unrestricted': bool(session.get('web_access_unrestricted', True))
            if current_user.is_authenticated else True,
        'can_menu': can_menu,
    }


def _load_web_access_into_session(userid=None):
    """Carga perfiles de menú en session (soft: falla → unrestricted)."""
    from web_access import apply_access_to_session, load_user_web_access
    uid = (userid or getattr(current_user, 'id', None) or session.get('login_userid') or '').strip()
    state = load_user_web_access(uid, get_db_connection)
    apply_access_to_session(session, state)
    return state


@app.before_request
def ensure_and_enforce_web_access():
    """Carga permisos si faltan y bloquea rutas sin menú asignado."""
    from database import is_receta_only_user
    from web_access import first_allowed_endpoint, resolve_menu_for_request, session_can_menu

    if not current_user.is_authenticated:
        return None
    if is_receta_only_user():
        return None

    if 'web_access_unrestricted' not in session:
        _load_web_access_into_session()

    ep = request.endpoint
    path = request.path or ''
    if path.startswith('/static/'):
        return None

    menu_code = resolve_menu_for_request(ep, path)
    if not menu_code:
        return None
    if session_can_menu(session, menu_code):
        return None
    # APIs de perfiles/asignación: quien tiene uno puede usar listados compartidos del otro
    if path.startswith('/api/') and menu_code in ('perfiles_acceso', 'asignar_perfiles') and (
        session_can_menu(session, 'perfiles_acceso') or session_can_menu(session, 'asignar_perfiles')
    ):
        return None

    # APIs → 403 JSON; páginas → redirect
    if path.startswith('/api/'):
        return jsonify({"error": "No tiene permiso para esta opción."}), 403

    flash('No tiene permiso para acceder a esa opción.', 'warning')
    target = first_allowed_endpoint(session)
    try:
        return redirect(url_for(target))
    except Exception:
        return redirect(url_for('dashboard'))


def _jsonable_value(value):
    if value is None:
        return None
    if isinstance(value, Decimal):
        return float(value)
    if isinstance(value, datetime):
        return value.strftime('%d/%m/%Y')
    if isinstance(value, date):
        return value.strftime('%d/%m/%Y')
    return value


def _report_column_name(name):
    """La primera columna del SP no tiene alias; pyodbc puede devolver '' → periodo_fmt."""
    if name is None:
        return 'periodo_fmt'
    if isinstance(name, str) and not name.strip():
        return 'periodo_fmt'
    return name


def _normalize_pr_period_vacacion(period_raw):
    """Acepta YYYYMM o YYYYMMDD; devuelve solo dígitos (6 u 8)."""
    s = str(period_raw or '').strip().replace('-', '').replace('/', '')
    if len(s) >= 8 and s[:8].isdigit():
        return s[:8]
    if len(s) >= 6 and s[:6].isdigit():
        return s[:6]
    return s


def _format_prperiod_mes(period_raw):
    """YYYYMM o YYYYMMDD → YYYY-MM para pantalla."""
    s = str(period_raw or '').strip().replace('-', '').replace('/', '')
    if len(s) >= 6 and s[:6].isdigit():
        return f'{s[:4]}-{s[4:6]}'
    return str(period_raw or '').strip()


def _xlastuser_id():
    """UserID de sesión (no nombre de usuario)."""
    return str(getattr(current_user, 'id', '') or '')[:20]


def _normalize_pr_period(period_raw):
    """
    PRPeriod en BD es yyyymmdd (8 dígitos), p. ej. 20251212.
    Acepta también '2025-12-12' o '2025/12/12' por si el valor llegó formateado.
    """
    s = str(period_raw or '').strip().replace('-', '').replace('/', '')
    if len(s) >= 8 and s[:8].isdigit():
        return s[:8]
    return str(period_raw or '').strip()


def _ejercicio_utilidades_from_period(period_raw):
    """
    Ejercicio de utilidades = año del periodo de pago menos uno.
    Ej.: utilidad calculada en marzo 2026 (periodo 202603…) → ejercicio 2025.
    """
    period = _normalize_pr_period(period_raw)
    if len(period) >= 4 and period[:4].isdigit():
        return str(int(period[:4]) - 1)
    return ''


def _normalize_date_yyyymmdd(fecha_raw):
    """Fecha para filtros SQL (CHAR 8)."""
    d = _parse_fecha_flexible(fecha_raw)
    if d:
        return d.strftime('%Y%m%d')
    s = str(fecha_raw or '').strip().replace('-', '').replace('/', '')
    if len(s) >= 8 and s[:8].isdigit():
        return s[:8]
    return ''


def _tregistro_params_from_json(body):
    body = body or {}
    activos = str(body.get('activos') or 'S').strip().upper()
    if activos not in ('S', 'N'):
        activos = 'S'
    return {
        'cia': str(body.get('cia') or '').strip(),
        'fecha_desde': _normalize_date_yyyymmdd(body.get('fecha_desde')),
        'fecha_hasta': _normalize_date_yyyymmdd(body.get('fecha_hasta')),
        'activos': activos,
    }


def _tregistro_validar_params(p):
    if not p.get('cia'):
        return 'Seleccione compañía.'
    if not p.get('fecha_desde') or not p.get('fecha_hasta'):
        return 'Indique fecha desde y fecha hasta.'
    if p['fecha_desde'] > p['fecha_hasta']:
        return 'La fecha desde no puede ser mayor que la fecha hasta.'
    return None


TREGISTRO_ARCHIVO_EXTENSION = {
    '04': 'ide',
    '05': 'tra',
    '11': 'per',
    '17': 'est',
    '29': 'edu',
    '30': 'cta',
}


def _tregistro_archivos_from_json(body):
    archivos = body.get('archivos') if isinstance(body, dict) else None
    if not isinstance(archivos, list):
        return []
    resultado = []
    for item in archivos:
        codigo = str(item or '').strip()
        if codigo and codigo not in resultado:
            resultado.append(codigo)
    return resultado


def _tregistro_personas_from_json(body):
    rows = body.get('rows') if isinstance(body, dict) else None
    if not isinstance(rows, list):
        return []
    personas = []
    for row in rows:
        if not isinstance(row, dict):
            continue
        person = str(row.get('person') or '').strip()
        if person and person not in personas:
            personas.append(person)
    return personas


def _tregistro_filename(ruc, codigo_estructura):
    """Nomenclatura T-Registro (ej. RP_20123456789.ide para estructura 04)."""
    digits = ''.join(ch for ch in str(ruc or '') if ch.isdigit())
    ruc11 = digits.zfill(11)[-11:] if digits else '00000000000'
    ext = TREGISTRO_ARCHIVO_EXTENSION.get(str(codigo_estructura), 'txt')
    return f'RP_{ruc11}.{ext}'


def _tregistro_valor_campo(row, column):
    aliases = {
        'DocIssuingCountry': 'docissuingcountry',
        'Block': 'block',
        'Block2': 'block2',
        'codeLDN': 'codeldn',
    }
    key = aliases.get(column, column)
    if key in row:
        return row.get(key)
    lower = str(key).lower()
    for k, v in row.items():
        if str(k).lower() == lower:
            return v
    return row.get(column)


def _tregistro_fecha_ddmmyyyy(valor):
    d = _parse_fecha_flexible(valor)
    if d:
        return d.strftime('%d/%m/%Y')
    s = str(valor or '').strip()
    if len(s) == 8 and s.isdigit():
        return f'{s[6:8]}/{s[4:6]}/{s[0:4]}'
    return ''


def _tregistro_campo_linea(row, column, max_len):
    """Replica wf_get_line de PowerBuilder (w_pr_treg_structure_04)."""
    doc_type = str(_tregistro_valor_campo(row, 'documenttype') or '').strip()
    if doc_type.isdigit():
        doc_type = doc_type.zfill(2)

    direccion1 = {
        'streettype', 'streetname', 'addressnumber', 'room', 'inside', 'apple',
        'lot', 'kilometer', 'Block', 'stage', 'zone', 'zonename', 'reference', 'localite',
    }
    direccion2 = {
        'streettype2', 'streetname2', 'addressnumber2', 'room2', 'inside2', 'apple2',
        'lot2', 'kilometer2', 'Block2', 'stage2', 'zone2', 'zonename2', 'reference2', 'localite2',
    }

    if column == 'birthdate':
        if doc_type == '06' or not _tregistro_valor_campo(row, 'birthdate'):
            return '|'
        fecha = _tregistro_fecha_ddmmyyyy(_tregistro_valor_campo(row, 'birthdate'))
        return (fecha + '|') if fecha else '|'

    if column in direccion1:
        if doc_type in ('01', '06'):
            return '|'
        valor = _tregistro_valor_campo(row, column)
        if valor is None or str(valor).strip() == '':
            return '|'
        return str(valor).strip()[:max_len] + '|'

    if column in direccion2:
        indicator = str(_tregistro_valor_campo(row, 'indicator') or '').strip()
        if indicator in ('0', '1'):
            return '|'
        valor = _tregistro_valor_campo(row, column)
        if valor is None or str(valor).strip() == '':
            return '|'
        return str(valor).strip()[:max_len] + '|'

    valor = _tregistro_valor_campo(row, column)
    if valor is None or str(valor).strip() == '':
        return '|'
    if max_len and max_len > 0:
        return str(valor).strip()[:max_len] + '|'
    return str(valor).strip() + '|'


