def _add_months_to_date(base_date, months):
    from calendar import monthrange

    month_index = base_date.month - 1 + int(months)
    year = base_date.year + month_index // 12
    month = month_index % 12 + 1
    day = min(base_date.day, monthrange(year, month)[1])
    return date(year, month, day)


def _normalize_periodo_yyyymm(period_raw):
    """Normaliza periodo tributario PLAME (YYYYMM) desde YYYYMM, YYYY-MM o YYYYMMDD."""
    s = str(period_raw or '').strip().replace('-', '').replace('/', '')
    if len(s) >= 6 and s[:6].isdigit():
        mm = int(s[4:6])
        if 1 <= mm <= 12:
            return s[:6]
    norm = _normalize_pr_period(period_raw)
    if len(norm) >= 6 and norm[:6].isdigit():
        mm = int(norm[4:6])
        if 1 <= mm <= 12:
            return norm[:6]
    return ''


def _validar_rango_periodos_reporte(desde_raw, hasta_raw, max_meses=12):
    """
    Normaliza rango de periodos tributarios (YYYYMM) y valida:
      - periodos válidos
      - desde <= hasta
      - rango máximo de max_meses meses
    Devuelve (periodo_desde, periodo_hasta, error).
    """
    desde_yyyymm = _normalize_periodo_yyyymm(desde_raw)
    hasta_yyyymm = _normalize_periodo_yyyymm(hasta_raw)
    if len(desde_yyyymm) != 6 or len(hasta_yyyymm) != 6:
        return None, None, 'Seleccione periodos válidos (desde y hasta).'
    try:
        desde_dt = date(int(desde_yyyymm[:4]), int(desde_yyyymm[4:6]), 1)
        hasta_dt = date(int(hasta_yyyymm[:4]), int(hasta_yyyymm[4:6]), 1)
    except Exception:
        return None, None, 'Seleccione periodos válidos (desde y hasta).'
    if hasta_dt < desde_dt:
        return None, None, 'El periodo hasta debe ser mayor o igual al periodo desde.'
    limite = _add_months_to_date(desde_dt, max_meses)
    if hasta_dt > limite:
        return None, None, f'El rango de periodos no puede superar {max_meses} meses.'
    return desde_yyyymm, hasta_yyyymm, None


def _boleta_filename_token(text, fallback='X'):
    """Normaliza texto para nombre de archivo: MAYÚSCULAS, sin acentos, solo A-Z0-9_."""
    raw = str(text or '').strip()
    if not raw:
        return fallback
    normalized = unicodedata.normalize('NFKD', raw)
    ascii_txt = ''.join(c for c in normalized if not unicodedata.combining(c)).upper()
    safe = re.sub(r'[^A-Z0-9]+', '_', ascii_txt).strip('_')
    while '__' in safe:
        safe = safe.replace('__', '_')
    return safe or fallback


def _boleta_period_label(period_raw):
    """Convierte periodo yyyymmdd/yyyymm a etiqueta JUNIO2026."""
    meses = {
        '01': 'ENERO', '02': 'FEBRERO', '03': 'MARZO', '04': 'ABRIL',
        '05': 'MAYO', '06': 'JUNIO', '07': 'JULIO', '08': 'AGOSTO',
        '09': 'SEPTIEMBRE', '10': 'OCTUBRE', '11': 'NOVIEMBRE', '12': 'DICIEMBRE',
    }
    period = re.sub(r'[^0-9]+', '', _normalize_pr_period(period_raw) or '')
    if len(period) >= 6:
        return f"{meses.get(period[4:6], 'MES')}{period[:4]}"
    return period or 'PERIODO'


def _boleta_pdf_filename(person, period_raw, nombre=None):
    """Nombre: boleta_JUAN_PEREZ_70978388_JUNIO2026.pdf"""
    name_part = _boleta_filename_token(nombre, fallback='')
    person_part = _boleta_filename_token(person, fallback='PREVIEW')
    period_part = _boleta_period_label(period_raw)
    if name_part:
        return f'boleta_{name_part}_{person_part}_{period_part}.pdf'
    return f'boleta_{person_part}_{period_part}.pdf'


def _merge_pdf_buffers(pdf_buffers):
    """Une varios PDF (BytesIO o bytes) en un solo BytesIO con pypdf."""
    from pypdf import PdfReader, PdfWriter

    writer = PdfWriter()
    for item in pdf_buffers or []:
        if item is None:
            continue
        if isinstance(item, (bytes, bytearray)):
            raw = bytes(item)
        else:
            try:
                item.seek(0)
            except Exception:
                pass
            raw = item.read() if hasattr(item, 'read') else bytes(item)
        if not raw:
            continue
        reader = PdfReader(io.BytesIO(raw))
        for page in reader.pages:
            writer.add_page(page)
    out = io.BytesIO()
    writer.write(out)
    out.seek(0)
    return out


