def _formato_liquidacion_fc_valor(formula_values, *codes, default=0.0):
    formula_values = formula_values or {}
    for code in codes:
        if code not in formula_values:
            continue
        try:
            return float(formula_values.get(code) or 0)
        except (TypeError, ValueError):
            return default
    return default


def _formato_liquidacion_cantidad(val):
    try:
        n = float(val or 0)
    except (TypeError, ValueError):
        n = 0.0
    if n == int(n):
        return str(int(n))
    text = f'{n:.2f}'.rstrip('0').rstrip('.')
    return text or '0'


def _formato_liquidacion_formulacodes_requeridos():
    codes = {
        code
        for row in _FORMATO_LIQ_REMUNERACION_DEF
        for code in (row.get('cts'), row.get('grati'), row.get('vaca'))
        if code
    }
    codes.update(_FORMATO_LIQ_CTS_FORMULACODES)
    codes.update(_FORMATO_LIQ_GRATI_FORMULACODES)
    codes.update(_FORMATO_LIQ_VACA_FORMULACODES)
    codes.update(_FORMATO_LIQ_TABLA_CONCEPTOS_FORMULACODES)
    codes.update(_FORMATO_LIQ_CABECERA_FORMULACODES)
    return sorted(codes)


def _fetch_formato_liquidacion_formulacodes(cursor, cia, payroll_type, period, person):
    codes = _formato_liquidacion_formulacodes_requeridos()
    if not codes:
        return {}

    placeholders = ','.join('?' for _ in codes)
    sql = f"""
        SELECT
            C.FormulaCode AS formula_code,
            SUM(ISNULL(EC.ConceptValueLo, EC.ConceptValue)) AS valor
        FROM PR_EmployeePayRollConcept EC (NOLOCK)
            INNER JOIN PR_Concept C (NOLOCK) ON EC.Concept = C.Concept
        WHERE EC.Company = ?
          AND EC.Person = ?
          AND EC.PayRollType = ?
          AND EC.PRPeriod = ?
          AND EXISTS (
                SELECT 1
                FROM PR_ProcessType PT (NOLOCK)
                WHERE PT.ShortName = 'LIQUIDACION'
                  AND PT.ProcessType = EC.ProcessType
            )
          AND C.FormulaCode IN ({placeholders})
        GROUP BY C.FormulaCode
    """
    cursor.execute(sql, (cia, person, payroll_type, period, *codes))
    rows = _dicts_first_nonempty_resultset(cursor)
    valores = {}
    for row in rows:
        fc = str(row.get('formula_code') or '').strip()
        if not fc:
            continue
        try:
            valores[fc] = float(row.get('valor') or 0)
        except (TypeError, ValueError):
            valores[fc] = 0.0
    return valores


def _build_formato_liquidacion_remuneracion(formula_values):
    formula_values = formula_values or {}
    filas = []
    totales = {'cts': 0.0, 'grati': 0.0, 'vaca': 0.0}
    totales_fc = {'cts': [], 'grati': [], 'vaca': []}
    es_divisa = False
    try:
        from database import get_active_database
        es_divisa = str(get_active_database() or '').strip().lower() == 'hm_divisa'
    except Exception:
        es_divisa = False
    for defn in _FORMATO_LIQ_REMUNERACION_DEF:
        label = defn['label']
        if es_divisa and defn.get('cts') == 'BONO_PROD_CTS':
            label = 'Promedio Descanso'
        fila = {'label': label}
        for col in ('cts', 'grati', 'vaca'):
            fc = defn.get(col)
            valor = float(formula_values.get(fc, 0) or 0) if fc else 0.0
            totales[col] += valor
            fila[f'{col}_fmt'] = _formato_liquidacion_moneda(valor)
            fila[f'{col}_fc'] = fc or ''
            if fc:
                totales_fc[col].append(fc)
        filas.append(fila)
    totales_fmt = {
        col: _formato_liquidacion_moneda(totales[col])
        for col in ('cts', 'grati', 'vaca')
    }
    totales_fc_fmt = {
        col: ' + '.join(totales_fc[col]) if totales_fc[col] else ''
        for col in ('cts', 'grati', 'vaca')
    }
    return filas, totales_fmt, totales, totales_fc_fmt


def _build_formato_liquidacion_trunca(total_base, formula_values, meses_code, dias_code, dias_falta_code=None):
    """Ingreso trunco: (base/12)*meses + (base/360)*días."""
    formula_values = formula_values or {}
    try:
        base = float(total_base or 0)
    except (TypeError, ValueError):
        base = 0.0
    try:
        meses = float(formula_values.get(meses_code) or 0)
    except (TypeError, ValueError):
        meses = 0.0
    try:
        dias = float(formula_values.get(dias_code) or 0)
    except (TypeError, ValueError):
        dias = 0.0

    x_mes = (base / 12.0) * meses if base else 0.0
    x_dia = (base / 360.0) * dias if base else 0.0
    total = x_mes + x_dia

    base_fmt = _formato_liquidacion_moneda(base)
    meses_txt = _formato_liquidacion_cantidad(meses)
    dias_txt = _formato_liquidacion_cantidad(dias)
    resultado = {
        'base_fmt': base_fmt,
        'meses_txt': meses_txt,
        'dias_txt': dias_txt,
        'meses_label': f'{meses_txt} MESES',
        'dias_label': f'{dias_txt} DIAS',
        'formula_meses': f'({base_fmt} / 12)',
        'formula_dias': f'({base_fmt} / 360)',
        'x_mes_fmt': _formato_liquidacion_moneda(x_mes),
        'x_dia_fmt': _formato_liquidacion_moneda(x_dia),
        'total_fmt': _formato_liquidacion_moneda(total),
        'total': total,
        'meses_fc': meses_code or '',
        'dias_fc': dias_code or '',
        'dias_falta_fc': dias_falta_code or '',
        'formula_meses_fc': f'(Σ rem.CTS / 12) × {meses_code}' if meses_code else '',
        'formula_dias_fc': f'(Σ rem.CTS / 360) × {dias_code}' if dias_code else '',
    }
    if dias_falta_code:
        try:
            dias_falta = float(formula_values.get(dias_falta_code) or 0)
        except (TypeError, ValueError):
            dias_falta = 0.0
        resultado['dias_falta_txt'] = _formato_liquidacion_cantidad(dias_falta)
    return resultado


def _formato_liquidacion_porcentaje_desde_concepto(importe, base):
    try:
        importe_val = float(importe or 0)
        base_val = float(base or 0)
    except (TypeError, ValueError):
        return ''
    if base_val <= 0 or importe_val <= 0:
        return ''
    return _formato_liquidacion_porcentaje((importe_val / base_val) * 100.0)


def _build_formato_liquidacion_tabla_conceptos(defn_rows, formula_values, liq=None, base_formula_code='TOTAL_REM_AFP'):
    """Filas % / base / importe desde conceptos del proceso LIQUIDACION."""
    formula_values = formula_values or {}
    liq = liq or {}
    base = _formato_liquidacion_fc_valor(formula_values, base_formula_code)
    base_fmt = _formato_liquidacion_moneda(base)

    filas = []
    total = 0.0
    cero_fmt = _formato_liquidacion_moneda(0)
    for defn in defn_rows:
        if defn.get('placeholder'):
            importe = (
                _formato_liquidacion_fc_valor(formula_values, defn['formula_code'])
                if defn.get('formula_code')
                else 0.0
            )
            total += importe
            filas.append({
                'label': defn['label'],
                'pct_fmt': '',
                'base_fmt': '',
                'importe_fmt': _formato_liquidacion_moneda(importe),
                'importe': importe,
                'formula_code': defn.get('formula_code') or '',
                'base_formula_code': '',
                'pct_formula_code': '',
            })
            continue
        importe = _formato_liquidacion_fc_valor(formula_values, defn['formula_code'])
        total += importe
        pct_formula_code = defn.get('pct_formula_code')
        pct_field = defn.get('pct_field')
        if pct_formula_code:
            pct_fmt = _formato_liquidacion_porcentaje(
                _formato_liquidacion_fc_valor(formula_values, pct_formula_code),
                mostrar_cero=bool(defn.get('pct_mostrar_cero')),
            )
        elif pct_field:
            pct_fmt = _formato_liquidacion_porcentaje(
                liq.get(pct_field),
                mostrar_cero=bool(defn.get('pct_mostrar_cero')),
            )
        else:
            pct_fmt = _formato_liquidacion_porcentaje_desde_concepto(importe, base)
        filas.append({
            'label': defn['label'],
            'pct_fmt': pct_fmt,
            'base_fmt': base_fmt,
            'importe_fmt': _formato_liquidacion_moneda(importe),
            'importe': importe,
            'formula_code': defn.get('formula_code') or '',
            'base_formula_code': base_formula_code if not defn.get('placeholder') else '',
            'pct_formula_code': pct_formula_code or '',
        })

    return {
        'filas': filas,
        'total_fmt': _formato_liquidacion_moneda(total),
        'total': total,
        'base_formula_code': base_formula_code,
    }


def _build_formato_liquidacion_descuentos(liq, formula_values):
    return _build_formato_liquidacion_tabla_conceptos(
        _FORMATO_LIQ_DESCUENTOS_DEF, formula_values, liq=liq
    )


def _build_formato_liquidacion_aportaciones(liq, formula_values):
    return _build_formato_liquidacion_tabla_conceptos(
        _FORMATO_LIQ_APORTACIONES_DEF, formula_values, liq=liq
    )


def _build_formato_liquidacion_cts(total_remuneracion_cts, formula_values):
    resultado = _build_formato_liquidacion_trunca(
        total_remuneracion_cts,
        formula_values,
        'C_CTSMESES',
        'DIAS_CTS_TRUNCO',
        'XFALTASCTS',
    )
    formula_values = formula_values or {}
    x_mes = _formato_liquidacion_fc_valor(formula_values, 'CTSXMES')
    x_dia = _formato_liquidacion_fc_valor(formula_values, 'CTSXDIA')
    resultado['x_mes_fmt'] = _formato_liquidacion_moneda(x_mes)
    resultado['x_dia_fmt'] = _formato_liquidacion_moneda(x_dia)
    total = x_mes + x_dia
    resultado['total'] = total
    resultado['total_fmt'] = _formato_liquidacion_moneda(total)
    resultado['x_mes_fc'] = 'CTSXMES'
    resultado['x_dia_fc'] = 'CTSXDIA'
    resultado['total_fc'] = 'CTSXMES + CTSXDIA'
    resultado['formula_meses_fc'] = '(Σ rem.CTS / 12) × C_CTSMESES → CTSXMES'
    resultado['formula_dias_fc'] = '(Σ rem.CTS / 360) × DIAS_CTS_TRUNCO → CTSXDIA'
    return resultado


def _build_formato_liquidacion_grati(total_remuneracion_grati, formula_values):
    resultado = _build_formato_liquidacion_trunca(
        total_remuneracion_grati,
        formula_values,
        'NUMERO_MESES',
        'NUMERO_DIAS',
        'XFALTASGRATI',
    )
    formula_values = formula_values or {}
    x_mes = _formato_liquidacion_fc_valor(formula_values, 'GRATI_TRUNCA')
    resultado['formula_meses'] = f"({resultado['base_fmt']} / 6)"
    resultado['x_mes_fmt'] = _formato_liquidacion_moneda(x_mes)
    dias = _formato_liquidacion_fc_valor(formula_values, 'NUMERO_DIAS')
    try:
        base = float(total_remuneracion_grati or 0)
    except (TypeError, ValueError):
        base = 0.0
    x_dia = (base / 180.0) * dias if base else 0.0
    resultado['formula_dias'] = f"({resultado['base_fmt']} / 180)"
    resultado['x_dia_fmt'] = _formato_liquidacion_moneda(x_dia)
    try:
        total = float((formula_values or {}).get('GRATI_TRUNCA') or 0)
    except (TypeError, ValueError):
        total = 0.0
    resultado['total'] = total
    resultado['total_fmt'] = _formato_liquidacion_moneda(total)
    try:
        bono_9 = float((formula_values or {}).get('BONIF_EXTRA_ESSALUD') or 0)
    except (TypeError, ValueError):
        bono_9 = 0.0
    resultado['bono_9'] = bono_9
    resultado['bono_9_fmt'] = _formato_liquidacion_moneda(bono_9)
    resultado['x_mes_fc'] = 'GRATI_TRUNCA'
    resultado['x_dia_fc'] = '(Σ rem.GRATI / 180) × NUMERO_DIAS'
    resultado['total_fc'] = 'GRATI_TRUNCA'
    resultado['bono_9_fc'] = 'BONIF_EXTRA_ESSALUD'
    resultado['formula_meses_fc'] = '(Σ rem.GRATI / 6) × NUMERO_MESES → GRATI_TRUNCA'
    resultado['formula_dias_fc'] = '(Σ rem.GRATI / 180) × NUMERO_DIAS'
    return resultado


def _formato_liquidacion_importe_formula(formula_values, code, calc_val):
    if code in (formula_values or {}):
        try:
            return float(formula_values.get(code) or 0)
        except (TypeError, ValueError):
            return calc_val
    return calc_val


def _build_formato_liquidacion_vaca(total_remuneracion_vaca, formula_values):
    """Vacaciones truncas: años + meses + días (misma lógica extendida que CTS)."""
    formula_values = formula_values or {}
    try:
        base = float(total_remuneracion_vaca or 0)
    except (TypeError, ValueError):
        base = 0.0

    anios = _formato_liquidacion_fc_valor(formula_values, 'ANIOSVACTRUNCA')
    meses = _formato_liquidacion_fc_valor(formula_values, 'MESES_VAC_TRUN')
    dias = _formato_liquidacion_fc_valor(formula_values, 'DIAS_VAC_TRUN')

    x_anio = _formato_liquidacion_fc_valor(formula_values, 'VACACIONANIO')
    x_mes = _formato_liquidacion_fc_valor(formula_values, 'VACXMES')
    x_dia = _formato_liquidacion_fc_valor(formula_values, 'VACXDIA')
    total = x_anio + x_mes + x_dia

    base_fmt = _formato_liquidacion_moneda(base)
    anios_txt = _formato_liquidacion_cantidad(anios)
    meses_txt = _formato_liquidacion_cantidad(meses)
    dias_txt = _formato_liquidacion_cantidad(dias)
    dias_falta = _formato_liquidacion_fc_valor(formula_values, 'XFALTASVACA', 'DIASFALTAVACLIQ')
    devolucion_quinta = _formato_liquidacion_fc_valor(formula_values, 'DEVOLUCION_QUINTA')
    otros_ingresos_afectos = _formato_liquidacion_fc_valor(formula_values, 'LIQINGRESOAFECTO')
    indemnizacion_despido = _formato_liquidacion_fc_valor(formula_values, 'INDEMNIZACION_DESPID')

    def _mostrar_ingreso(val):
        try:
            return abs(float(val or 0)) > 0.005
        except (TypeError, ValueError):
            return False

    return {
        'base_fmt': base_fmt,
        'anios_label': f'{anios_txt} AÑOS',
        'meses_label': f'{meses_txt} MESES',
        'dias_label': f'{dias_txt} DIAS',
        'formula_anios': base_fmt,
        'formula_meses': f'({base_fmt} / 12)',
        'formula_dias': f'({base_fmt} / 360)',
        'x_anio_fmt': _formato_liquidacion_moneda(x_anio),
        'x_mes_fmt': _formato_liquidacion_moneda(x_mes),
        'x_dia_fmt': _formato_liquidacion_moneda(x_dia),
        'total_fmt': _formato_liquidacion_moneda(total),
        'total': total,
        'dias_falta_txt': _formato_liquidacion_cantidad(dias_falta),
        'devolucion_quinta': devolucion_quinta,
        'devolucion_quinta_fmt': _formato_liquidacion_moneda(devolucion_quinta),
        'mostrar_devolucion_quinta': _mostrar_ingreso(devolucion_quinta),
        'otros_ingresos_afectos': otros_ingresos_afectos,
        'otros_ingresos_afectos_fmt': _formato_liquidacion_moneda(otros_ingresos_afectos),
        'mostrar_otros_ingresos_afectos': _mostrar_ingreso(otros_ingresos_afectos),
        'indemnizacion_despido': indemnizacion_despido,
        'indemnizacion_despido_fmt': _formato_liquidacion_moneda(indemnizacion_despido),
        'mostrar_indemnizacion_despido': _mostrar_ingreso(indemnizacion_despido),
        'anios_fc': 'ANIOSVACTRUNCA',
        'meses_fc': 'MESES_VAC_TRUN',
        'dias_fc': 'DIAS_VAC_TRUN',
        'dias_falta_fc': 'XFALTASVACA / DIASFALTAVACLIQ',
        'x_anio_fc': 'VACACIONANIO',
        'x_mes_fc': 'VACXMES',
        'x_dia_fc': 'VACXDIA',
        'total_fc': 'VACACIONANIO + VACXMES + VACXDIA',
        'devolucion_quinta_fc': 'DEVOLUCION_QUINTA',
        'otros_ingresos_afectos_fc': 'LIQINGRESOAFECTO',
        'indemnizacion_despido_fc': 'INDEMNIZACION_DESPID',
        'formula_anios_fc': 'Σ rem.VACA × ANIOSVACTRUNCA → VACACIONANIO',
        'formula_meses_fc': '(Σ rem.VACA / 12) × MESES_VAC_TRUN → VACXMES',
        'formula_dias_fc': '(Σ rem.VACA / 360) × DIAS_VAC_TRUN → VACXDIA',
    }


def _contexto_formato_liquidacion(params, include_images=True):
    """Datos compartidos del formato de liquidación (PDF y vista analista)."""
    cia_param = str(params.get('cia') or '').strip()
    if not cia_param and has_request_context():
        ensure_user_session()
    cia = str(cia_param or (session.get('company') if has_request_context() else '') or '').strip()
    payroll_type = str(params.get('payroll_type') or '').strip()
    period = _normalize_pr_period(params.get('period'))
    person = str(params.get('person') or '').strip()
    if not (cia and payroll_type and period and person):
        raise ValueError('Faltan parámetros para generar el formato de liquidación.')

    conn = None
    formula_values = {}
    try:
        conn = get_db_connection()
        cursor = conn.cursor()
        _set_cursor_timeout(cursor)
        rows = _exec_sp_rows_dicts(
            cursor,
            'EXEC sp_pr_formatoliquidacion_web @cia=?, @payrolltype=?, @period=?, @person=?',
            (cia, payroll_type, period, person),
        )
        formula_values = _fetch_formato_liquidacion_formulacodes(
            cursor, cia, payroll_type, period, person
        )
    finally:
        if conn:
            try:
                conn.close()
            except Exception:
                pass

    liq = rows[0] if rows else {}
    if not liq:
        raise ValueError('No se encontraron datos para el formato de liquidación.')

    logo_src = ''
    firma_src = ''
    if include_images:
        logo_src, firma_src = _boleta_logo_firma_src(cia)
        if _es_cliente_ngservicios():
            firma_src = ''

    cero = _formato_liquidacion_moneda(0)
    cero_pct = '0.00%'
    (
        remuneracion_rows,
        remuneracion_totales,
        remuneracion_totales_raw,
        remuneracion_totales_fc,
    ) = _build_formato_liquidacion_remuneracion(formula_values)
    cts_calc = _build_formato_liquidacion_cts(remuneracion_totales_raw.get('cts'), formula_values)
    grati_calc = _build_formato_liquidacion_grati(remuneracion_totales_raw.get('grati'), formula_values)
    vaca_calc = _build_formato_liquidacion_vaca(remuneracion_totales_raw.get('vaca'), formula_values)
    total_ingresos = (
        float(cts_calc.get('total') or 0)
        + float(grati_calc.get('total') or 0)
        + float(vaca_calc.get('total') or 0)
        + float(grati_calc.get('bono_9') or 0)
        + float(vaca_calc.get('devolucion_quinta') or 0)
        + float(vaca_calc.get('otros_ingresos_afectos') or 0)
        + float(vaca_calc.get('indemnizacion_despido') or 0)
    )
    total_ingresos_fmt = _formato_liquidacion_moneda(total_ingresos)
    descuentos_calc = _build_formato_liquidacion_descuentos(liq, formula_values)
    aportaciones_calc = _build_formato_liquidacion_aportaciones(liq, formula_values)
    neto_a_pagar = total_ingresos - float(descuentos_calc.get('total') or 0)
    neto_a_pagar_fmt = _formato_liquidacion_moneda(neto_a_pagar)

    return {
        'cia': cia,
        'payroll_type': payroll_type,
        'period': period,
        'person': person,
        'liq': liq,
        'formula_values': formula_values,
        'logo_src': logo_src,
        'firma_src': firma_src,
        'regimen_pensionario': _regimen_pensionario_formato_liquidacion(liq),
        'basico_fmt': _formato_liquidacion_moneda(liq.get('basico')),
        'basico_fc': 'LIQ_REM_BASICA',
        'anios_servicio_fc': 'ANIO',
        'meses_servicio_fc': 'MES',
        'dias_servicio_fc': 'DIA',
        'entry_date_fmt': _formato_liquidacion_fecha(liq.get('entry_date')),
        'cease_date_fmt': _formato_liquidacion_fecha(liq.get('cease_date')),
        'cero': cero,
        'cero_pct': cero_pct,
        'remuneracion_rows': remuneracion_rows,
        'remuneracion_totales': remuneracion_totales,
        'remuneracion_totales_fc': remuneracion_totales_fc,
        'cts_calc': cts_calc,
        'grati_calc': grati_calc,
        'vaca_calc': vaca_calc,
        'total_ingresos_fmt': total_ingresos_fmt,
        'descuentos_calc': descuentos_calc,
        'aportaciones_calc': aportaciones_calc,
        'neto_a_pagar_fmt': neto_a_pagar_fmt,
        'es_ngservicios': _es_cliente_ngservicios(),
    }


def generar_pdf_formato_liquidacion(params):
    ctx = _contexto_formato_liquidacion(params, include_images=True)
    html_renderizado = render_template('formato_liquidacion_pdf.html', **ctx)

    if WEASYPRINT_AVAILABLE:
        pdf_io = io.BytesIO()
        HTML(string=html_renderizado).write_pdf(pdf_io)
        pdf_io.seek(0)
        return pdf_io

    raise RuntimeError(
        'WeasyPrint no está disponible para generar el formato de liquidación. '
        + str(_WEASYPRINT_IMPORT_ERROR or '')
    )


def enviar_correo_formato_liquidacion(destinatario, nombre_empleado, periodo, sexo, pdf_io, person=None):
    if not destinatario or '@' not in str(destinatario):
        return False, 'Sin correo'

    resend.api_key = _resend_api_key()
    if not resend.api_key:
        return False, 'RESEND_API_KEY no configurada.' + _resend_api_key_diagnostico()
    remitente = _env_var('MAIL_FROM', 'EMAIL_FROM', default='onboarding@resend.dev')

    try:
        sexo_val = int(sexo)
    except Exception:
        sexo_val = 0
    trato = 'Estimada' if sexo_val == 2 else 'Estimado'
    periodo_legible = formatear_periodo_texto(periodo)
    pdf_base64 = base64.b64encode(pdf_io.getvalue()).decode('utf-8')

    try:
        params = {
            'from': f'Recursos Humanos <{remitente}>',
            'to': destinatario,
            'subject': f'Formato de Liquidación - {periodo_legible} - {nombre_empleado}',
            'html': f"""
                <p>{trato} {nombre_empleado},</p>
                <p>Le hacemos entrega de su formato de liquidación correspondiente al periodo de <b>{periodo_legible}</b>.</p>
                <p>Saludos,<br>Recursos Humanos</p>
            """,
            'attachments': [
                {
                    'content': pdf_base64,
                    'filename': _formato_liquidacion_pdf_filename(person or nombre_empleado, periodo),
                }
            ],
        }
        resend.Emails.send(params)
        return True, 'Enviado'
    except Exception as e:
        logging.error('Error en Resend formato liquidación: %s', str(e))
        return False, str(e)


