@login_manager.user_loader
def load_user(user_id):
    from database import _restore_client_database_from_login_cache
    _restore_client_database_from_login_cache()
    user = User.get_user_by_id(user_id)
    if user:
        _cache_session_user(user)
        return user
    return _user_from_session_cache(user_id)


@app.route('/')
def login():
    if current_user.is_authenticated:
        from database import is_receta_only_user
        if is_receta_only_user():
            return redirect(url_for('receta_page'))
        return redirect(url_for('dashboard'))
    return render_template('login.html')


@app.route('/login', methods=['POST'])
def login_post():
    username = (request.form.get('username') or '').strip()
    password = request.form.get('password') or ''
    user = User.validate_user(username, password)
    if user:
        session['login_userid'] = username
        login_user(user)
        _cache_session_user(user)
        session.pop('web_session_loaded', None)
        session.pop('web_user_no_employee', None)
        ensure_user_session()
        _load_web_access_into_session(username)
        from database import is_receta_only_user
        from web_access import first_allowed_endpoint
        if is_receta_only_user(username):
            return redirect(url_for('receta_page'))
        return redirect(url_for(first_allowed_endpoint(session)))
    flash('Usuario o contraseña incorrectos.', 'error')
    return redirect(url_for('login'))


@app.route('/cambiar-password', methods=['POST'])
def change_password_route():
    username = (request.form.get('username') or '').strip()
    old_password = request.form.get('old_password') or ''
    new_password = request.form.get('new_password') or ''
    confirm = request.form.get('confirm_password') or ''
    if new_password != confirm:
        flash('Las contraseñas nuevas no coinciden.', 'error')
        return redirect(url_for('login'))
    ok_pwd, msg_pwd = validar_password_fuerte(new_password)
    if not ok_pwd:
        flash(msg_pwd, 'error')
        return redirect(url_for('login'))
    user = User.validate_user(username, old_password)
    if not user:
        flash('Usuario o contraseña anterior incorrectos.', 'error')
        return redirect(url_for('login'))
    from database import resolve_client_database
    target_db = resolve_client_database(username) or session.get('client_database')
    ok, msg = cambiar_password(user.id, old_password, new_password, database=target_db)
    flash(msg, 'success' if ok else 'error')
    return redirect(url_for('login'))


