def _selector_items_from_sp(cursor, sp_sql, params):
    """Ejecuta un SP selector y devuelve lista {id, text}."""
    cursor.execute(sp_sql, params)
    col_names = [str(c[0]).strip() for c in (cursor.description or [])]
    items = []
    for row in cursor.fetchall():
        rd = _row_dict_from_columns(col_names, row)
        item_id = rd.get('id') if rd.get('id') is not None else rd.get('bank')
        item_text = rd.get('text') if rd.get('text') is not None else rd.get('name')
        if item_id is None:
            continue
        items.append({'id': str(item_id).strip(), 'text': str(item_text or item_id).strip()})
    return items


def _cargar_selectores_bancario(cursor, cia):
    bancos = _selector_items_from_sp(cursor, 'EXEC sp_pr_selectorbancos_web @cia=?', (cia,))
    formas_pago = _selector_items_from_sp(cursor, 'EXEC sp_pr_selectorformapago_web @cia=?', (cia,))
    tipos_cuenta = _selector_items_from_sp(cursor, 'EXEC sp_pr_selectortipocuenta_web @cia=?', (cia,))
    return bancos, formas_pago, tipos_cuenta


def _cargar_selectores_pensiones(cursor, cia):
    pension_types = _selector_items_from_sp(cursor, 'EXEC sp_pr_selectorpensiontype_web @cia=?', (cia,))
    regime_health = _selector_items_from_sp(cursor, 'EXEC sp_pr_selectorregimehealth_web @cia=?', (cia,))
    return pension_types, regime_health


def _cargar_selectores_laborales(cursor, cia):
    employee_types = _selector_items_from_sp(
        cursor, 'EXEC sp_pr_selectoremployeetype_web @cia=?', (cia,)
    )
    employee_categories = _selector_items_from_sp(
        cursor, 'EXEC sp_pr_selectoremployeecategory_web @cia=?', (cia,)
    )
    contract_modalities = _selector_items_from_sp(
        cursor, 'EXEC sp_pr_selectorcontractmodality_web @cia=?', (cia,)
    )
    ocupations = _selector_items_from_sp(
        cursor, 'EXEC sp_pr_selectorocupation_web @cia=?', (cia,)
    )
    special_statuses = _selector_items_from_sp(
        cursor, 'EXEC sp_pr_selectorspecialstatus_web @cia=?', (cia,)
    )
    positions = _selector_items_from_sp(
        cursor, 'EXEC sp_pr_selectorposition_web @cia=?', (cia,)
    )
    cost_centers = _selector_items_from_sp(
        cursor, 'EXEC sp_pr_selectorcostcenter_web @cia=?', (cia,)
    )
    account_profiles = _selector_items_from_sp(
        cursor, 'EXEC sp_pr_selectoraccountprofile_web @cia=?', (cia,)
    )
    cease_reasons = _selector_items_from_sp(
        cursor, 'EXEC sp_pr_selectorceasereason_web @cia=?', (cia,)
    )
    cursor.execute('EXEC sp_pr_selectorplanillas_web @cia=?', (cia,))
    col_names = [str(c[0]).strip() for c in (cursor.description or [])]
    payroll_types = []
    for row in cursor.fetchall():
        rd = _row_dict_from_columns(col_names, row)
        item_id = rd.get('payrolltype') or rd.get('PayRollType')
        item_text = rd.get('tipoplanilla') or rd.get('Description') or item_id
        if item_id is None:
            continue
        payroll_types.append({'id': str(item_id).strip(), 'text': str(item_text or item_id).strip()})
    return (
        employee_types,
        employee_categories,
        contract_modalities,
        ocupations,
        special_statuses,
        positions,
        cost_centers,
        payroll_types,
        account_profiles,
        cease_reasons,
    )


