@app.route('/api/tareo-ng/importar/procesar', methods=['POST'])
@login_required
def api_tareo_ng_importar_procesar():
    if not _es_cliente_ngservicios():
        return jsonify({"error": "Módulo Tareo NG no disponible en esta base."}), 404
    body = request.get_json(silent=True) or {}
    cia = str(body.get('cia') or body.get('company') or session.get('company') or '').strip()
    period = _tareong_period_yyyymm(body.get('period') or body.get('prperiod'))
    if not cia:
        return jsonify({"error": "Seleccione una compañía."}), 400
    if not period:
        return jsonify({"error": "Seleccione un periodo."}), 400
    conn = None
    try:
        conn = get_db_connection()
        cursor = conn.cursor()
        _set_cursor_timeout_payroll(cursor)
        cursor.execute("SELECT COUNT(*) FROM PR_TAREONG (NOLOCK)")
        total = int((cursor.fetchone() or [0])[0])
        if total == 0:
            return jsonify({"error": "No hay datos importados."}), 400
        ko = _tareong_count_ko(cursor)
        if ko > 0:
            return jsonify({
                "error": f"No se puede procesar: hay {ko} fila(s) con Result = KO. Corrija y valide de nuevo.",
                "total_ko": ko,
            }), 400
        cursor.execute(
            "EXEC SP_PR_CargaTareoMasivoNG @period=?, @cia=?",
            (period, cia),
        )
        _drain_pyodbc_cursor(cursor)
        conn.commit()

        # Cuántos trabajadores quedaron en PR_REGISTERHOUR para el periodo.
        personas_reg = 0
        try:
            cursor.execute(
                """
                SELECT COUNT(DISTINCT Person)
                FROM PR_REGISTERHOUR WITH (NOLOCK)
                WHERE LTRIM(RTRIM(Company)) = ?
                  AND CONVERT(varchar(6), RegisterDate, 112) = ?
                """,
                (cia, period),
            )
            personas_reg = int((cursor.fetchone() or [0])[0] or 0)
        except Exception:
            logging.exception("tareo_ng conteo registerhour post-proceso")

        return jsonify({
            "ok": True,
            "mensaje": (
                f"Proceso concluido. {total} fila(s) de importación → "
                f"{personas_reg} trabajador(es) en PR_REGISTERHOUR para {period}."
            ),
            "total_filas": total,
            "personas_registradas": personas_reg,
        })
    except Exception as e:
        if conn:
            try:
                conn.rollback()
            except Exception:
                pass
        logging.exception("api_tareo_ng_importar_procesar")
        return jsonify({"error": _sp_error_message(e)}), 500
    finally:
        if conn:
            try:
                conn.close()
            except Exception:
                pass

