@app.route('/api/asientos/distribucion-porcentual/replicar', methods=['POST'])
@login_required
def api_distribucion_porcentual_replicar():
    """sp_pr_replicar_distribucion_voucher_web: si vacío copia periodo anterior; siempre agrega activos faltantes."""
    # Temporal: en hm_divisa no auto-replicar (solo listar lo existente).
    from database import get_active_database
    if str(get_active_database() or '').strip().lower() == 'hm_divisa':
        return jsonify({
            "ok": True,
            "skipped": True,
            "copiados": 0,
            "nuevos": 0,
            "mensaje": "Réplica deshabilitada temporalmente en hm_divisa.",
        })

    body = request.get_json(silent=True) or {}
    cia = str(body.get('cia') or body.get('company') or '').strip()
    period = str(body.get('period') or body.get('periodo') or '').strip()
    if not cia or not period:
        return jsonify({"error": "Seleccione compañía y periodo."}), 400

    conn = None
    try:
        conn = get_db_connection()
        cursor = conn.cursor()
        cursor.execute(
            "EXEC sp_pr_replicar_distribucion_voucher_web "
            "@company=?, @period=?, @xlastuser=?",
            (cia, period, _xlastuser_id()),
        )
        rows = _dicts_first_nonempty_resultset(cursor)
        conn.commit()
        row = rows[0] if rows else {}
        period_origen = str(row.get('period_origen') or '').strip()
        if len(period_origen) == 8 and period_origen.isdigit():
            period_origen_fmt = (
                f"{period_origen[0:4]}-{period_origen[4:6]}-{period_origen[6:8]}"
            )
        else:
            period_origen_fmt = period_origen or ''
        try:
            copiados = int(row.get('copiados') or 0)
        except (TypeError, ValueError):
            copiados = 0
        try:
            nuevos = int(row.get('nuevos') or 0)
        except (TypeError, ValueError):
            nuevos = 0
        # Mensaje armado en Python (UTF-8) para evitar mojibake del SP vía sqlcmd.
        if copiados > 0 and nuevos > 0:
            mensaje = (
                f"Distribución replicada desde el periodo {period_origen_fmt}. "
                f"Copiados: {copiados}. Nuevos activos: {nuevos}."
            )
        elif copiados > 0:
            mensaje = (
                f"Distribución replicada desde el periodo {period_origen_fmt}. "
                f"Copiados: {copiados}."
            )
        elif nuevos > 0:
            mensaje = (
                f"Se agregaron {nuevos} trabajador(es) activo(s) sin distribución "
                f"(unidad de ficha, 100%)."
            )
        else:
            mensaje = "Sin cambios. La distribución del periodo ya está actualizada."
        return jsonify({
            "ok": True,
            "period_origen": _jsonable_value(row.get('period_origen')),
            "period_destino": _jsonable_value(row.get('period_destino')),
            "copiados": copiados,
            "nuevos": nuevos,
            "mensaje": mensaje,
        })
    except Exception as e:
        if conn:
            try:
                conn.rollback()
            except Exception:
                pass
        logging.exception("api_distribucion_porcentual_replicar")
        return jsonify({"error": _sp_error_message(e)}), 500
    finally:
        if conn:
            try:
                conn.close()
            except Exception:
                pass


