@app.route('/api/asientos/interfaz/generar-archivo', methods=['POST'])
@login_required
def api_asientos_interfaz_generar_archivo():
    """Genera archivo del asiento: Alvisoft TXT, Excel SAP Divisa o Excel El Clan."""
    from database import get_active_database
    from alvisoft_export import generar_txt_alvisoft
    from sap_divisa_export import generar_xls_sap_divisa
    from elclan_asiento_export import generar_xls_asiento_elclan

    body = request.get_json(silent=True) or {}
    cia = str(body.get('cia') or body.get('company') or '').strip()
    voucher = str(body.get('voucher') or '').strip()

    if not cia:
        return jsonify({"error": "Seleccione una compañía."}), 400
    if not voucher:
        return jsonify({"error": "Seleccione un asiento."}), 400

    active_db = str(get_active_database() or '').strip().lower()
    es_divisa = active_db == 'hm_divisa'
    es_elclan = active_db == 'hm_elclan'

    conn = None
    try:
        conn = get_db_connection()
        cursor = conn.cursor()
        if es_elclan:
            filename, contenido = generar_xls_asiento_elclan(cursor, cia, voucher)
            try:
                conn.commit()
            except Exception:
                pass
            resp = Response(
                contenido,
                mimetype='application/vnd.ms-excel',
            )
            resp.headers['Content-Disposition'] = f'attachment; filename="{filename}"'
            return resp

        if es_divisa:
            filename, contenido = generar_xls_sap_divisa(cursor, cia, voucher)
            try:
                conn.commit()
            except Exception:
                pass
            resp = Response(
                contenido,
                mimetype='application/vnd.ms-excel',
            )
            resp.headers['Content-Disposition'] = f'attachment; filename="{filename}"'
            return resp

        filename, contenido = generar_txt_alvisoft(cursor, cia, voucher)
        try:
            conn.commit()
        except Exception:
            pass
        resp = Response(
            contenido.encode('latin-1', errors='replace'),
            mimetype='text/plain; charset=iso-8859-1',
        )
        resp.headers['Content-Disposition'] = f'attachment; filename="{filename}"'
        return resp
    except ValueError as e:
        return jsonify({"error": str(e)}), 400
    except Exception as e:
        logging.exception("api_asientos_interfaz_generar_archivo")
        return jsonify({"error": _sp_error_message(e)}), 500
    finally:
        if conn:
            try:
                conn.close()
            except Exception:
                pass


