@app.route('/api/formulas/selectores-edicion', methods=['GET'])
@login_required
def api_formulas_selectores_edicion():
    """Selectores para edición de fórmulas en una sola petición (conceptos, procesos, etc.)."""
    cia = str(request.args.get('cia') or '').strip()
    payrolltype = str(request.args.get('payrolltype') or '').strip()
    if not cia or not payrolltype:
        return jsonify({"error": "Indique compañía y tipo de planilla."}), 400

    conn = None
    try:
        conn = get_db_connection()
        cursor = conn.cursor()

        cursor.execute("EXEC sp_pr_selectorconceptos_web @cia=?", (cia,))
        conceptos = [
            {"id": r.concept, "text": r.description}
            for r in cursor.fetchall()
        ]

        cursor.execute(
            "EXEC sp_pr_selectorprocesos_web @cia=?, @payrolltype=?",
            (cia, payrolltype),
        )
        procesos = [
            {"id": r.processtype, "text": r.proceso}
            for r in cursor.fetchall()
        ]

        cursor.execute("EXEC sp_pr_selectorparameter_web @company=?", (cia,))
        col_names = [str(c[0]).strip() for c in (cursor.description or [])]
        parameters = []
        for row in cursor.fetchall():
            rd = _row_dict_from_columns(col_names, row)
            parameters.append({"id": rd.get("id"), "text": rd.get("text")})

        cursor.execute("EXEC sp_pr_selectorparametroformula_web")
        col_names = [str(c[0]).strip() for c in (cursor.description or [])]
        parametros_formula = []
        for row in cursor.fetchall():
            rd = _row_dict_from_columns(col_names, row)
            parametros_formula.append({"id": rd.get("id"), "text": rd.get("text")})

        cursor.execute("EXEC sp_pr_selectorgrupoformula_web @company=?", (cia,))
        col_names = [str(c[0]).strip() for c in (cursor.description or [])]
        grupos = []
        for row in cursor.fetchall():
            rd = _row_dict_from_columns(col_names, row)
            grupos.append({"id": rd.get("id"), "text": rd.get("text")})

        return jsonify({
            "conceptos": conceptos,
            "procesos": procesos,
            "parameters": parameters,
            "parametros_formula": parametros_formula,
            "grupos": grupos,
        })
    except Exception as e:
        logging.exception("api_formulas_selectores_edicion")
        return jsonify({"error": str(e)}), 500
    finally:
        if conn:
            try:
                conn.close()
            except Exception:
                pass


@app.route('/api/formulas/guardar', methods=['POST'])
@login_required
def api_formulas_guardar():
    """sp_pr_guardarformula_web: alta / edición de fórmula."""
    body = request.get_json(silent=True) or {}
    cia = str(body.get('cia') or body.get('company') or '').strip()
    formulaheader = str(body.get('formulaheader') or '').strip()
    modo = str(body.get('modo') or ('U' if formulaheader else 'I')).strip().upper()

    payrolltype = str(body.get('payrolltype') or '').strip()
    proccestype = str(body.get('proccestype') or body.get('processtype') or '').strip()
    concept = str(body.get('concept') or '').strip()

    if not cia:
        return jsonify({"error": "Seleccione una compañía."}), 400
    if not payrolltype or not proccestype or not concept:
        return jsonify({"error": "Complete planilla, proceso y concepto."}), 400

    detalle_lineas = body.get('detalle') or []
    if not isinstance(detalle_lineas, list) or len(detalle_lineas) == 0:
        return jsonify({
            "error": "La fórmula debe tener al menos una línea de detalle.",
        }), 400

    orden = body.get('orden')
    try:
        orden = int(orden) if orden not in (None, '') else None
    except Exception:
        orden = None

    detalle_xml = _formulas_detalle_to_xml(detalle_lineas)

    conn = None
    try:
        conn = get_db_connection()
        cursor = conn.cursor()
        cursor.execute(
            "EXEC sp_pr_guardarformula_web "
            "@modo=?, @company=?, @formulaheader=?, @payrolltype=?, @proccestype=?, "
            "@concept=?, @description=?, @orden=?, @person=?, @period=?, @tipo=?, "
            "@conceptcond=?, @grupoformula=?, @flagtruncate=?, @formulacode=?, "
            "@parametroformula=?, @detalle_xml=?, @xlastuser=?",
            (
                modo,
                cia,
                formulaheader or None,
                payrolltype,
                proccestype,
                concept,
                str(body.get('description') or '').strip() or None,
                orden,
                str(body.get('person') or '').strip() or None,
                str(body.get('period') or '').strip() or None,
                str(body.get('tipo') or '').strip().upper()[:1] or None,
                str(body.get('conceptcond') or '').strip() or None,
                str(body.get('grupoformula') or '').strip() or None,
                _normalize_flag_yn(body.get('flagtruncate')),
                str(body.get('formulacode') or '').strip().upper() or None,
                str(body.get('parametroformula') or '').strip() or None,
                detalle_xml or None,
                _xlastuser_id(),
            ),
        )
        rows = _dicts_first_nonempty_resultset(cursor)
        conn.commit()
        row = rows[0] if rows else {}
        fh_id = str(row.get('formulaheader') or formulaheader or '').strip()
        return jsonify({
            "ok": True,
            "formulaheader": fh_id,
            "modo": _jsonable_value(row.get('modo')) or modo,
            "mensaje": _jsonable_value(row.get('mensaje')) or 'Guardado correctamente.',
        })
    except Exception as e:
        logging.exception("api_formulas_guardar")
        if conn:
            try:
                conn.rollback()
            except Exception:
                pass
        return jsonify({"error": str(e)}), 500
    finally:
        if conn:
            try:
                conn.close()
            except Exception:
                pass


@app.route('/api/formulas/eliminar', methods=['POST'])
@login_required
def api_formulas_eliminar():
    """sp_pr_eliminarformula_web: elimina fórmula(s) completa(s) (cabecera + detalle)."""
    body = request.get_json(silent=True) or {}
    cia = str(body.get('cia') or body.get('company') or '').strip()
    formulaheader = str(body.get('formulaheader') or '').strip()
    formulaheaders = body.get('formulaheaders') or []

    if not formulaheaders and formulaheader:
        formulaheaders = [formulaheader]
    formulaheaders = [
        str(fh or '').strip()
        for fh in formulaheaders
        if str(fh or '').strip()
    ]

    if not cia:
        return jsonify({"error": "Seleccione una compañía."}), 400
    if not formulaheaders:
        return jsonify({"error": "Seleccione al menos una fórmula."}), 400

    conn = None
    try:
        conn = get_db_connection()
        cursor = conn.cursor()
        eliminadas = []
        errores = []
        for fh in formulaheaders:
            try:
                cursor.execute(
                    "EXEC sp_pr_eliminarformula_web @company=?, @formulaheader=?",
                    (cia, fh),
                )
                rows = _dicts_first_nonempty_resultset(cursor)
                while cursor.nextset():
                    pass
                row = rows[0] if rows else {}
                eliminadas.append(_jsonable_value(row.get('formulaheader')) or fh)
            except Exception as ex:
                errores.append({"formulaheader": fh, "error": str(ex)})

        conn.commit()
        n_ok = len(eliminadas)
        n_err = len(errores)
        if n_ok == 0:
            return jsonify({
                "ok": False,
                "eliminadas": [],
                "errores": errores,
                "error": errores[0]['error'] if errores else "No se pudo eliminar.",
            }), 400

        mensaje = (
            f"Se eliminó 1 fórmula correctamente."
            if n_ok == 1 and n_err == 0
            else f"Se eliminaron {n_ok} fórmula(s) correctamente."
        )
        if n_err:
            mensaje += f" {n_err} con error."

        return jsonify({
            "ok": True,
            "eliminadas": eliminadas,
            "errores": errores,
            "mensaje": mensaje,
        })
    except Exception as e:
        logging.exception("api_formulas_eliminar")
        if conn:
            try:
                conn.rollback()
            except Exception:
                pass
        return jsonify({"error": str(e)}), 500
    finally:
        if conn:
            try:
                conn.close()
            except Exception:
                pass


@app.route('/api/formulas/copiar-planilla', methods=['POST'])
@login_required
def api_formulas_copiar_planilla():
    """Copia fórmulas marcadas a otro tipo de planilla dentro de la misma compañía.

    Body:
      cia, payrolltype (origen), processtype, payrolltype_dest,
      formulas[{formulaheader, formulacode}] (opcional si vacío: listado del filtro).
    """
    body = request.get_json(silent=True) or {}
    cia = str(body.get('cia') or body.get('company') or '').strip()
    payrolltype_orig = str(body.get('payrolltype') or '').strip()
    payrolltype_dest = str(
        body.get('payrolltype_dest') or body.get('payrolltype_destino') or ''
    ).strip()
    processtype = str(
        body.get('processtype') or body.get('proccestype') or ''
    ).strip()
    formulas = body.get('formulas') or []

    if not cia:
        return jsonify({"error": "Seleccione una compañía."}), 400
    if not payrolltype_dest:
        return jsonify({"error": "Seleccione la planilla destino."}), 400
    if payrolltype_orig and payrolltype_orig == payrolltype_dest:
        return jsonify({
            "error": "La planilla destino debe ser distinta a la planilla origen.",
        }), 400

    conn = None
    try:
        conn = get_db_connection()
        cursor = conn.cursor()

        if not formulas:
            if not payrolltype_orig or not processtype:
                return jsonify({
                    "error": (
                        "Indique fórmulas a copiar, o compañía + planilla origen "
                        "+ proceso para copiar el listado completo."
                    ),
                }), 400
            cursor.execute(
                """
                SELECT fh.FormulaHeader,
                       LTRIM(RTRIM(ISNULL(c.FormulaCode, fh.formulacode)))
                FROM PR_FormulaHeader fh (NOLOCK)
                LEFT JOIN PR_Concept c (NOLOCK)
                    ON fh.Concept = c.Concept AND fh.Company = c.Company
                WHERE fh.Company = ?
                  AND fh.Payrolltype = ?
                  AND fh.Proccestype = ?
                ORDER BY fh.orden ASC, fh.FormulaHeader ASC
                """,
                (cia, payrolltype_orig, processtype),
            )
            formulas = [
                {"formulaheader": str(r[0]).strip(), "formulacode": str(r[1] or '').strip()}
                for r in cursor.fetchall()
                if r and r[0]
            ]

        if not formulas:
            return jsonify({"error": "No hay fórmulas para copiar con el filtro indicado."}), 400

        ok = 0
        insertadas = 0
        actualizadas = 0
        errores = []
        userid = _xlastuser_id() or 'WEB'

        for item in formulas:
            fh = str((item or {}).get('formulaheader') or '').strip()
            if not fh:
                continue
            fc = str((item or {}).get('formulacode') or '').strip()
            concepto_desc = str((item or {}).get('concepto') or fh).strip()
            try:
                cursor.execute(
                    "EXEC sp_pr_copiar_formula_planilla_web "
                    "@cia=?, @formulaheader=?, @payrolltype_dest=?, @xlastuser=?",
                    (cia, fh, payrolltype_dest, userid),
                )
                row = None
                if cursor.description:
                    rows = cursor.fetchall()
                    if rows:
                        row = rows[0]
                while cursor.nextset():
                    if cursor.description:
                        rows = cursor.fetchall()
                        if rows:
                            row = rows[0]
                accion = ''
                if row and len(row) >= 2:
                    accion = str(row[1] or '').strip().upper()
                if accion == 'UPDATE':
                    actualizadas += 1
                else:
                    insertadas += 1
                ok += 1
            except Exception as ex:
                logging.exception(
                    "api_formulas_copiar_planilla fh=%s dest=%s", fh, payrolltype_dest
                )
                errores.append({
                    "formulaheader": fh,
                    "formulacode": fc,
                    "concepto": concepto_desc,
                    "error": str(ex),
                })

        conn.commit()
        n = len([i for i in formulas if str((i or {}).get('formulaheader') or '').strip()])
        partes = [f"Se copiaron {ok} fórmula(s) a la planilla destino."]
        if insertadas:
            partes.append(f"{insertadas} nueva(s).")
        if actualizadas:
            partes.append(f"{actualizadas} actualizada(s).")
        if errores:
            partes.append(f"{len(errores)} con error.")
        return jsonify({
            "ok": True,
            "copiadas": ok,
            "insertadas": insertadas,
            "actualizadas": actualizadas,
            "procesadas": n,
            "errores": errores,
            "mensaje": " ".join(partes),
        })
    except Exception as e:
        logging.exception("api_formulas_copiar_planilla")
        if conn:
            try:
                conn.rollback()
            except Exception:
                pass
        return jsonify({"error": str(e)}), 500
    finally:
        if conn:
            try:
                conn.close()
            except Exception:
                pass


@app.route('/api/formulas/replicar', methods=['POST'])
@login_required
def api_formulas_replicar():
    """Replica fórmulas de cia(+planilla+proceso) a las demás empresas activas.

    Body:
      cia (origen), formulas[{formulaheader, formulacode}], opcional:
      payrolltype, processtype (si formulas vacío, carga el listado del filtro),
      crear_conceptos (bool, default True): crea nemónicos faltantes en destino.
    """
    body = request.get_json(silent=True) or {}
    cia = str(body.get('cia') or body.get('company') or '').strip()
    payrolltype = str(body.get('payrolltype') or '').strip()
    processtype = str(
        body.get('processtype') or body.get('proccestype') or ''
    ).strip()
    formulas = body.get('formulas') or []
    crear_conceptos = body.get('crear_conceptos', True)
    if isinstance(crear_conceptos, str):
        crear_conceptos = crear_conceptos.strip().lower() in ('1', 'true', 's', 'y', 'yes')

    if not cia:
        return jsonify({"error": "Seleccione una compañía origen."}), 400

    conn = None
    try:
        conn = get_db_connection()
        cursor = conn.cursor()

        # Si no vienen fórmulas, cargar todas del filtro cia+planilla+proceso
        if not formulas:
            if not payrolltype or not processtype:
                return jsonify({
                    "error": (
                        "Indique fórmulas a replicar, o compañía + tipo de "
                        "planilla + proceso para replicar el listado completo."
                    ),
                }), 400
            cursor.execute(
                """
                SELECT fh.FormulaHeader,
                       LTRIM(RTRIM(ISNULL(c.FormulaCode, fh.formulacode)))
                FROM PR_FormulaHeader fh (NOLOCK)
                LEFT JOIN PR_Concept c (NOLOCK)
                    ON fh.Concept = c.Concept AND fh.Company = c.Company
                WHERE fh.Company = ?
                  AND fh.Payrolltype = ?
                  AND fh.Proccestype = ?
                ORDER BY fh.orden ASC, fh.FormulaHeader ASC
                """,
                (cia, payrolltype, processtype),
            )
            formulas = [
                {"formulaheader": str(r[0]).strip(), "formulacode": str(r[1] or '').strip()}
                for r in cursor.fetchall()
                if r and r[0]
            ]

        if not formulas:
            return jsonify({"error": "No hay fórmulas para replicar con el filtro indicado."}), 400

        ok = 0
        errores = []
        advertencias = []
        conceptos_creados = 0

        cursor.execute(
            """
            SELECT LTRIM(RTRIM(Company)) AS company
            FROM SY_Company (NOLOCK)
            WHERE ISNULL(status, 'A') = 'A'
              AND LTRIM(RTRIM(Company)) <> ?
            ORDER BY Company
            """,
            (cia,),
        )
        destinos = [
            str(r[0]).strip()
            for r in cursor.fetchall()
            if r and r[0]
        ]

        for item in formulas:
            fh = str((item or {}).get('formulaheader') or '').strip()
            fc = str((item or {}).get('formulacode') or '').strip()
            if not fh:
                continue

            cursor.execute(
                """
                SELECT LTRIM(RTRIM(ISNULL(c.FormulaCode, ''))),
                       ISNULL(c.Description, ''),
                       LTRIM(RTRIM(ISNULL(fh.formulacode, '')))
                FROM PR_FormulaHeader fh (NOLOCK)
                LEFT JOIN PR_Concept c (NOLOCK)
                    ON fh.Concept = c.Concept AND fh.Company = c.Company
                WHERE fh.Company = ? AND fh.FormulaHeader = ?
                """,
                (cia, fh),
            )
            row_meta = cursor.fetchone()
            if row_meta:
                fc_concepto = str(row_meta[0] or '').strip()
                concepto_desc = str(row_meta[1] or '').strip()
                fc_cabecera = str(row_meta[2] or '').strip()
                fc = fc_concepto or fc_cabecera or fc
            else:
                concepto_desc = fh

            if not concepto_desc:
                concepto_desc = fc or fh

            faltantes = []
            if fc:
                for dest in destinos:
                    cursor.execute(
                        """
                        SELECT 1
                        FROM PR_Concept (NOLOCK)
                        WHERE Company = ?
                          AND LTRIM(RTRIM(FormulaCode)) = ?
                        """,
                        (dest, fc),
                    )
                    if not cursor.fetchone():
                        faltantes.append(dest)

            if faltantes and crear_conceptos and fc:
                creados_ok = []
                creados_err = []
                for dest in faltantes:
                    try:
                        cursor.execute(
                            "EXEC sp_pr_replicar_nuevo_concepto_nemonico "
                            "@cia=?, @formulacode=?, @cia_origen=?",
                            (dest, fc, cia),
                        )
                        while cursor.nextset():
                            pass
                        creados_ok.append(dest)
                        conceptos_creados += 1
                    except Exception as ex_c:
                        creados_err.append(f"{dest}: {ex_c}")
                if creados_ok:
                    advertencias.append({
                        "formulaheader": fh,
                        "formulacode": fc,
                        "concepto": concepto_desc,
                        "mensaje": (
                            f"Concepto creado en: {', '.join(creados_ok)}."
                        ),
                        "empresas_creadas": creados_ok,
                    })
                if creados_err:
                    advertencias.append({
                        "formulaheader": fh,
                        "formulacode": fc,
                        "concepto": concepto_desc,
                        "mensaje": (
                            "No se pudo crear concepto en: "
                            + '; '.join(creados_err[:8])
                        ),
                        "empresas_faltantes": faltantes,
                    })
            elif faltantes:
                advertencias.append({
                    "formulaheader": fh,
                    "formulacode": fc,
                    "concepto": concepto_desc,
                    "mensaje": (
                        f"Concepto no existe en: {', '.join(faltantes)}. "
                        "Se replicará solo en empresas donde exista el concepto."
                    ),
                    "empresas_faltantes": faltantes,
                })

            try:
                cursor.execute(
                    "EXEC sp_pr_replicar_formula_cia @cia=?, @formulacode=?, @formulaheader=?",
                    (cia, fc or None, fh),
                )
                while cursor.nextset():
                    pass
                ok += 1
            except Exception as ex:
                errores.append({
                    "formulaheader": fh,
                    "formulacode": fc,
                    "concepto": concepto_desc,
                    "error": str(ex),
                })

        conn.commit()
        n = len([i for i in formulas if str((i or {}).get('formulaheader') or '').strip()])
        partes = [
            f"Se replicaron {ok} fórmula(s) desde {cia} hacia "
            f"{len(destinos)} empresa(s)."
        ]
        if errores:
            partes.append(f"{len(errores)} con error.")
        if conceptos_creados:
            partes.append(f"{conceptos_creados} concepto(s) creado(s) en destino.")
        return jsonify({
            "ok": True,
            "replicadas": ok,
            "procesadas": n,
            "empresas_destino": len(destinos),
            "conceptos_creados": conceptos_creados,
            "advertencias": advertencias,
            "errores": errores,
            "mensaje": " ".join(partes),
        })
    except Exception as e:
        logging.exception("api_formulas_replicar")
        if conn:
            try:
                conn.rollback()
            except Exception:
                pass
        return jsonify({"error": str(e)}), 500
    finally:
        if conn:
            try:
                conn.close()
            except Exception:
                pass


