@app.route('/api/conceptos/validar-cias', methods=['POST'])
@login_required
def api_conceptos_validar_cias():
    """sp_pr_validarconceptos_cias_web: conceptos filtrados ausentes o distintos en otras empresas."""
    body = request.get_json(silent=True) or {}
    cia = str(body.get('cia') or body.get('company') or '').strip()
    descripcion = str(body.get('descripcion') or body.get('busqueda') or body.get('q') or '').strip()
    tipos_raw = body.get('tipos')
    todos_tipos = body.get('todos_tipos')
    if todos_tipos is None:
        todos_tipos = tipos_raw is None
    tipos = _tipos_concepto_csv_param(tipos_raw)

    if not cia:
        return jsonify({"error": "Seleccione una compañía."}), 400
    if not todos_tipos and isinstance(tipos_raw, list) and len(tipos_raw) == 0:
        return jsonify({
            "ok": True,
            "cia_origen": cia,
            "total_origen": 0,
            "total_faltantes": 0,
            "total_diferencias": 0,
            "total_incidencias": 0,
            "empresas_con_incidencias": 0,
            "resumen": [],
            "rows": [],
            "mensaje": "No hay tipos de concepto seleccionados para validar.",
        })

    conn = None
    try:
        conn = get_db_connection()
        cursor = conn.cursor()
        cursor.execute(
            "EXEC sp_pr_validarconceptos_cias_web @company=?, @descripcion=?, @tipos=?",
            (cia, descripcion or None, tipos),
        )
        sets = _dicts_collect_nonempty_resultsets(cursor, max_sets=5)
        total_origen = 0
        resumen_rows = []
        detalle_rows = []
        for result in sets:
            if not result:
                continue
            sample = result[0]
            if 'total_origen' in sample:
                total_origen = int(sample.get('total_origen') or 0)
            elif 'faltantes' in sample and 'diferencias' in sample:
                resumen_rows = result
            elif 'tipo_validacion' in sample:
                detalle_rows = result
            elif 'formulacode' in sample:
                detalle_rows = result

        resumen = [_concepto_validacion_resumen_dict(r) for r in resumen_rows]
        detalle = [_concepto_validacion_cias_dict(r) for r in detalle_rows]
        total_faltantes = sum(1 for x in detalle if str(x.get('tipo_validacion') or '').upper() == 'FALTANTE')
        total_diferencias = sum(1 for x in detalle if str(x.get('tipo_validacion') or '').upper() == 'DIFERENCIA')
        total_incidencias = len(detalle)
        empresas_con_incidencias = sum(1 for x in resumen if int(x.get('total_incidencias') or 0) > 0)

        mensaje = None
        if total_origen == 0:
            mensaje = 'No hay conceptos que coincidan con los filtros indicados.'
        elif total_incidencias == 0:
            mensaje = (
                f'Todos los conceptos filtrados ({total_origen}) coinciden en las demás empresas activas.'
            )

        return jsonify({
            "ok": True,
            "cia_origen": cia,
            "total_origen": total_origen,
            "total_faltantes": total_faltantes,
            "total_diferencias": total_diferencias,
            "total_incidencias": total_incidencias,
            "empresas_con_incidencias": empresas_con_incidencias,
            "empresas_con_faltantes": empresas_con_incidencias,
            "resumen": resumen,
            "rows": detalle,
            "mensaje": mensaje,
        })
    except Exception as e:
        logging.exception("api_conceptos_validar_cias")
        return jsonify({"error": str(e)}), 500
    finally:
        if conn:
            try:
                conn.close()
            except Exception:
                pass


@app.route('/api/conceptos/replicar-cias', methods=['POST'])
@login_required
def api_conceptos_replicar_cias():
    """Replica un concepto por nemónico a las demás empresas activas (sp_pr_replicar_nuevo_concepto_nemonico)."""
    body = request.get_json(silent=True) or {}
    cia_origen = str(body.get('cia') or body.get('company') or '').strip()
    formulacode = str(body.get('formulacode') or '').strip()

    if not cia_origen or not formulacode:
        return jsonify({"error": "Indique compañía origen y nemónico."}), 400

    conn = None
    try:
        conn = get_db_connection()
        cursor = conn.cursor()
        cursor.execute(
            """
            SELECT LTRIM(RTRIM(Company)) AS company
            FROM SY_Company (NOLOCK)
            WHERE ISNULL(status, 'A') = 'A'
              AND LTRIM(RTRIM(Company)) <> ?
            ORDER BY Company
            """,
            (cia_origen,),
        )
        destinos = [
            str(r[0]).strip()
            for r in cursor.fetchall()
            if r and r[0]
        ]

        creados = []
        omitidos = []
        errores = []

        for dest in destinos:
            try:
                cursor.execute(
                    "EXEC sp_pr_replicar_nuevo_concepto_nemonico @cia=?, @formulacode=?, @cia_origen=?",
                    (dest, formulacode, cia_origen),
                )
                rows = _dicts_first_nonempty_resultset(cursor)
                msg = str((rows[0] or {}).get('mensaje') or '').lower() if rows else ''
                if 'ya existe' in msg:
                    omitidos.append(dest)
                else:
                    creados.append(dest)
            except Exception as ex:
                errores.append({"company": dest, "error": str(ex)})

        conn.commit()

        partes = []
        if creados:
            partes.append('Replicado en todas las empresas.')
        if omitidos:
            partes.append(f"Ya existía en {len(omitidos)} empresa(s): {', '.join(omitidos)}.")
        if errores:
            det_err = '; '.join(
                f"{e.get('company')}: {e.get('error')}" for e in errores[:5]
            )
            if len(errores) > 5:
                det_err += f" (+{len(errores) - 5} más)"
            partes.append(f"{len(errores)} error(es): {det_err}.")
        if not partes:
            partes.append('No hay otras empresas activas para replicar.')

        return jsonify({
            "ok": True,
            "cia_origen": cia_origen,
            "formulacode": formulacode,
            "creados": creados,
            "omitidos": omitidos,
            "errores": errores,
            "mensaje": ' '.join(partes),
        })
    except Exception as e:
        logging.exception("api_conceptos_replicar_cias")
        if conn:
            try:
                conn.rollback()
            except Exception:
                pass
        return jsonify({"error": str(e)}), 500
    finally:
        if conn:
            try:
                conn.close()
            except Exception:
                pass


