def _tregistro_yn(raw, default='N'):
    s = str(raw or default).strip().upper()[:1]
    return s if s in ('Y', 'N') else default


@app.route('/api/tregistro-importacion/campos-nuevos/listar', methods=['POST'])
@login_required
def api_tregistro_campos_nuevos_listar():
    """Lista trabajadores recién registrados con los campos a completar post T-Registro."""
    body = request.get_json(silent=True) or {}
    cia = str(body.get('cia') or body.get('company') or '').strip()
    persons_raw = body.get('persons') or body.get('personas') or []
    if isinstance(persons_raw, str):
        persons = [p.strip() for p in persons_raw.split(',') if p.strip()]
    else:
        persons = [str(p or '').strip() for p in persons_raw if str(p or '').strip()]

    if not cia:
        return jsonify({"error": "Seleccione una compañía."}), 400
    if not persons:
        return jsonify({"error": "No hay trabajadores nuevos para actualizar."}), 400

    # Limitar tamaño razonable
    persons = persons[:500]
    placeholders = ','.join('?' for _ in persons)
    sql = f"""
        SELECT
            e.Person AS person,
            ISNULL(NULLIF(LTRIM(RTRIM(e.EmployeeCode)), ''), e.Person) AS codigo,
            ISNULL(p.DocumentNumber, e.Person) AS documento,
            LTRIM(RTRIM(ISNULL(p.Name, ''))) AS nombre,
            LTRIM(RTRIM(ISNULL(e.Position, ''))) AS position,
            LTRIM(RTRIM(ISNULL(e.CostCenter, ''))) AS costcenter,
            LTRIM(RTRIM(ISNULL(e.AccountProfile, ''))) AS accountprofile,
            CASE WHEN UPPER(LTRIM(RTRIM(ISNULL(e.FlagAsigFamiliar, 'N')))) = 'Y' THEN 'Y' ELSE 'N' END AS flagasigfamiliar,
            CASE WHEN UPPER(LTRIM(RTRIM(ISNULL(e.FlagMixta, 'N')))) = 'Y' THEN 'Y' ELSE 'N' END AS flagmixta
        FROM PR_Employee e (NOLOCK)
        INNER JOIN SY_Person p (NOLOCK) ON p.Person = e.Person
        WHERE e.Company = ?
          AND e.Person IN ({placeholders})
        ORDER BY p.Name, e.Person
    """
    conn = None
    try:
        conn = get_db_connection()
        cursor = conn.cursor()
        cursor.execute(sql, [cia] + persons)
        rows = _dicts_first_nonempty_resultset(cursor)
        resultado = []
        for r in rows:
            resultado.append({
                'person': _jsonable_value(r.get('person')),
                'codigo': _jsonable_value(r.get('codigo')),
                'documento': _jsonable_value(r.get('documento')),
                'nombre': _jsonable_value(r.get('nombre')),
                'position': _jsonable_value(r.get('position')) or '',
                'costcenter': _jsonable_value(r.get('costcenter')) or '',
                'accountprofile': _jsonable_value(r.get('accountprofile')) or '',
                'flagasigfamiliar': _tregistro_yn(r.get('flagasigfamiliar')),
                'flagmixta': _tregistro_yn(r.get('flagmixta')),
            })
        return jsonify({"rows": resultado, "total": len(resultado)})
    except Exception as e:
        logging.exception("api_tregistro_campos_nuevos_listar")
        return jsonify({"error": str(e)}), 500
    finally:
        if conn:
            try:
                conn.close()
            except Exception:
                pass


@app.route('/api/tregistro-importacion/campos-nuevos/guardar', methods=['POST'])
@login_required
def api_tregistro_campos_nuevos_guardar():
    """sp_pr_tregistro_actualizar_campos_nuevos_web: actualiza cargo/CC/perfil/asig fam/AFP mixta."""
    body = request.get_json(silent=True) or {}
    cia = str(body.get('cia') or body.get('company') or '').strip()
    items = body.get('items') or body.get('filas') or []
    if not cia:
        return jsonify({"error": "Seleccione una compañía."}), 400
    if not isinstance(items, list) or not items:
        return jsonify({"error": "No hay filas para guardar."}), 400

    conn = None
    ok_count = 0
    errores = []
    try:
        conn = get_db_connection()
        cursor = conn.cursor()
        xuser = _xlastuser_id()
        for idx, item in enumerate(items):
            if not isinstance(item, dict):
                continue
            person = str(item.get('person') or '').strip()
            if not person:
                errores.append({"fila": idx + 1, "person": "", "error": "Falta person."})
                continue
            try:
                cursor.execute(
                    "EXEC sp_pr_tregistro_actualizar_campos_nuevos_web "
                    "@cia=?, @person=?, @position=?, @costcenter=?, @accountprofile=?, "
                    "@flagasigfamiliar=?, @flagmixta=?, @xlastuser=?",
                    (
                        cia,
                        person,
                        str(item.get('position') or '').strip() or None,
                        str(item.get('costcenter') or '').strip() or None,
                        str(item.get('accountprofile') or '').strip() or None,
                        _tregistro_yn(item.get('flagasigfamiliar')),
                        _tregistro_yn(item.get('flagmixta')),
                        xuser,
                    ),
                )
                # drain result
                _dicts_first_nonempty_resultset(cursor)
                ok_count += 1
            except Exception as ex_item:
                logging.exception("api_tregistro_campos_nuevos_guardar item %s", person)
                errores.append({
                    "fila": idx + 1,
                    "person": person,
                    "nombre": str(item.get('nombre') or '').strip(),
                    "error": str(ex_item),
                })
        conn.commit()
        if ok_count == 0 and errores:
            return jsonify({
                "error": "No se pudo guardar ninguna fila.",
                "errores": errores,
            }), 400
        return jsonify({
            "ok": True,
            "guardados": ok_count,
            "errores": errores,
            "mensaje": (
                f"Se actualizaron {ok_count} trabajador(es)."
                if not errores
                else f"Actualizados: {ok_count}. Con error: {len(errores)}."
            ),
        })
    except Exception as e:
        logging.exception("api_tregistro_campos_nuevos_guardar")
        try:
            if conn:
                conn.rollback()
        except Exception:
            pass
        return jsonify({"error": str(e)}), 500
    finally:
        if conn:
            try:
                conn.close()
            except Exception:
                pass


def _plame_sunat_obtener_carga(cursor, cia, period):
    cursor.execute(
        "EXEC sp_pr_plame_sunat_obtener_carga_web @cia=?, @period=?",
        (cia, period),
    )
    rows = _dicts_first_nonempty_resultset(cursor)
    return rows[0] if rows else None


def _plame_sunat_carga_a_json(row):
    if not row:
        return None
    uploaded_at = row.get('uploadedat')
    if isinstance(uploaded_at, datetime):
        uploaded_at = uploaded_at.strftime('%Y-%m-%d %H:%M:%S')
    return {
        'cargaid': row.get('cargaid'),
        'company': row.get('company'),
        'period': row.get('period'),
        'ruc': row.get('ruc'),
        'employername': row.get('employername'),
        'periodosunat': row.get('periodosunat'),
        'filer01name': row.get('filer01name'),
        'filer04name': row.get('filer04name'),
        'filer05name': row.get('filer05name'),
        'rowsr01': int(row.get('rowsr01') or 0),
        'rowsr04': int(row.get('rowsr04') or 0),
        'rowsr05': int(row.get('rowsr05') or 0),
        'uploadedat': uploaded_at,
        'uploadedby': row.get('uploadedby'),
    }


def _plame_sunat_validar_archivos(parsed_bundle, filenames, cia, period):
    metas = [parsed_bundle[t]['meta'] for t in ARCHIVOS_SUNAT]
    rucs = {m.get('ruc') for m in metas if m.get('ruc')}
    if len(rucs) != 1:
        return 'Los tres XML deben corresponder al mismo RUC.'
    periodos = {m.get('period_yyyymm') for m in metas if m.get('period_yyyymm')}
    if len(periodos) != 1:
        return 'Los tres XML deben corresponder al mismo periodo tributario.'
    periodo_xml = next(iter(periodos))
    if periodo_xml != period:
        return (
            f'El periodo del XML ({periodo_xml}) no coincide con el seleccionado ({period}).'
        )
    for tipo in ARCHIVOS_SUNAT:
        fn_info = parse_filename(filenames.get(tipo))
        if fn_info and fn_info.get('period') != period:
            return f'El nombre de {tipo} no coincide con el periodo seleccionado.'
        if fn_info and fn_info.get('tipo') != tipo:
            return f'El archivo {filenames.get(tipo)} no corresponde a {tipo}.'
    return None


def _plame_sunat_guardar_carga(conn, cia, period, parsed_bundle, filenames, username):
    meta = parsed_bundle['R01']['meta']
    cursor = conn.cursor()
    cursor.execute(
        "EXEC sp_pr_plame_sunat_eliminar_carga_web @cia=?, @period=?",
        (cia, period),
    )
    _drain_pyodbc_cursor(cursor)
    cursor.execute(
        """
        INSERT INTO PR_PlameSunatCarga (
            Company, Period, Ruc, EmployerName, PeriodoSunat,
            FileR01Name, FileR04Name, FileR05Name,
            RowsR01, RowsR04, RowsR05, UploadedBy
        )
        OUTPUT INSERTED.CargaId
        VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
        """,
        (
            cia,
            period,
            meta.get('ruc') or '',
            (meta.get('employername') or '')[:300],
            (meta.get('periodosunat') or '')[:7],
            (filenames.get('R01') or '')[:260],
            (filenames.get('R04') or '')[:260],
            (filenames.get('R05') or '')[:260],
            parsed_bundle['R01']['rows_count'],
            parsed_bundle['R04']['rows_count'],
            parsed_bundle['R05']['rows_count'],
            (username or '')[:50],
        ),
    )
    row = cursor.fetchone()
    if not row or row[0] is None:
        _drain_pyodbc_cursor(cursor)
        row = _plame_sunat_obtener_carga(cursor, cia, period)
        carga_id = int(row.get('cargaid') or 0) if row else 0
    else:
        carga_id = int(row[0])
    if not carga_id:
        raise RuntimeError('No se pudo registrar la cabecera de la carga SUNAT.')

    insert_sql = """
        INSERT INTO PR_PlameSunatFila (
            CargaId, Archivo, NumFila, TipoDoc, DocumentNumber,
            LastName1, LastName2, Names, Situacion, MontosJson
        ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
    """
    params = []
    for tipo in ARCHIVOS_SUNAT:
        for fila in parsed_bundle[tipo]['filas']:
            params.append((
                carga_id,
                fila['archivo'],
                fila['num_fila'],
                fila['tipodoc'],
                fila['documentnumber'],
                fila['lastname1'][:100],
                fila['lastname2'][:100],
                fila['names'][:200],
                fila['situacion'][:80],
                fila['montos_json'],
            ))
    batch_size = 50
    for i in range(0, len(params), batch_size):
        cursor.executemany(insert_sql, params[i:i + batch_size])
    conn.commit()
    return carga_id


@app.route('/api/plame/validar/estado', methods=['GET'])
@login_required
def api_plame_validar_estado():
    """Estado de la carga SUNAT R01/R04/R05 para compañía y periodo."""
    cia = str(request.args.get('cia') or '').strip()
    period = _plame_period_yyyymm(request.args.get('period'))
