    safe_payroll = re.sub(r'[^A-Za-z0-9_\\-]+', '_', payroll_type).strip('_') or 'PLANILLA'
    nombre_zip = f'Formatos_Utilidades_{safe_company}_{safe_period}_{safe_payroll}.zip'
