def _fecha_tabla_json(val):
    """Serializa fecha/datetime para columnas de listados (JSON)."""
    if val is None:
        return ''
    if isinstance(val, datetime):
        return val.strftime('%d/%m/%Y')
    if isinstance(val, date):
        return val.strftime('%d/%m/%Y')
    return str(val).strip()


def _validacion_planilla_rows_to_mensajes(rows):
    """Filas person/name/observacion de SP de validación → mensajes legibles."""
    mensajes = []
    for r in rows:
        person = str(r.get('person') or '').strip()
        name = str(r.get('name') or '').strip()
        obs = str(r.get('observacion') or '').strip()
        if not obs:
            continue
        if person or name:
            etiqueta = ' — '.join([p for p in [person, name] if p])
            mensajes.append(f'{etiqueta}: {obs}')
        else:
            mensajes.append(obs)
    return mensajes


def _validar_pre_calculo_planilla_mensajes(cursor, cia, payrolltype, processtype):
    """sp_pr_validar_pre_calculo_web → permanentes duplicados + vías (mensual/FIN_DE_MES).

    En hm_aci/hm_aci2 + mensual el SP omite el formulador (solo maestro vs procedimiento).
    """
    cursor.execute(
        "EXEC sp_pr_validar_pre_calculo_web "
        "@cia=?, @payrolltype=?, @processtype=?",
        (cia, payrolltype, processtype),
    )
    rows = _dicts_first_nonempty_resultset(cursor)
    return _validacion_planilla_rows_to_mensajes(rows)


def _proceso_aplica_validacion_post_calculo(cursor, cia, processtype):
    """Validaciones post-cálculo (panel amarillo) solo para mensual / fin de mes."""
    cursor.execute(
        """
        SELECT
            UPPER(LTRIM(RTRIM(ISNULL(ShortName, '')))) AS shortname,
            UPPER(LTRIM(RTRIM(ISNULL(Description, '')))) AS description
        FROM PR_ProcessType
        WHERE Company = ? AND ProcessType = ?
        """,
        (cia, processtype),
    )
    row = cursor.fetchone()
    if not row:
        return False
    shortname = str(_cursor_row_field(row, 'shortname', 0) or '').strip().upper()
    description = str(_cursor_row_field(row, 'description', 1) or '').strip().upper()
    if shortname == 'FIN_DE_MES':
        return True
    if description == 'MENSUAL' or 'FIN DE MES' in description:
        return True
    return False


def _validar_calculo_planilla_mensajes(cursor, cia, payrolltype, processtype, period):
    """sp_pr_validar_calculo_web → lista de mensajes para el panel de validaciones."""
    if not _proceso_aplica_validacion_post_calculo(cursor, cia, processtype):
        return []
    cursor.execute(
        "EXEC sp_pr_validar_calculo_web "
        "@cia=?, @payrolltype=?, @processtype=?, @period=?",
        (cia, payrolltype, processtype, period),
    )
    rows = _dicts_first_nonempty_resultset(cursor)
    return _validacion_planilla_rows_to_mensajes(rows)


@app.route('/api/procesar-planilla/trabajadores-calculo', methods=['POST'])
@login_required
def api_procesar_planilla_trabajadores():
    """sp_pr_calcularplanillas_web @cia, @payrolltype, @processtype, @period, @cesados, @repunit, @accountprofile."""
    body = request.get_json(silent=True) or {}
    cia = str(body.get('cia') or '').strip()
    payrolltype = str(body.get('payrolltype') or '').strip()
    processtype = str(body.get('processtype') or body.get('proceso') or '').strip()
    period = _normalize_pr_period(body.get('period'))
    cesados = str(body.get('cesados') or 'T').strip().upper()
    if cesados not in ('T', 'Y', 'N'):
        cesados = 'T'
    repunit = str(body.get('repunit') or body.get('unidad') or '0').strip()
    if not repunit:
        repunit = '0'
    if len(repunit) > 20:
        repunit = repunit[:20]
    accountprofile = str(
        body.get('accountprofile') or body.get('perfil_contable') or ''
    ).strip()
    if accountprofile in ('0', '*'):
        accountprofile = ''
    if len(accountprofile) > 20:
        accountprofile = accountprofile[:20]
    if not cia or not payrolltype or not processtype or not period:
        return jsonify({"error": "Faltan compañía, tipo de planilla, proceso o periodo."}), 400
    conn = None
    try:
        conn = get_db_connection()
        cursor = conn.cursor()
        cursor.execute(
            "EXEC sp_pr_calcularplanillas_web "
            "@cia=?, @payrolltype=?, @processtype=?, @period=?, @cesados=?, @repunit=?, @accountprofile=?",
            (cia, payrolltype, processtype, period, cesados, repunit, accountprofile or None),
        )
        rows = _dicts_first_nonempty_resultset(cursor)
        trabajadores = [
            {
                "person": str(r.get("person") or "").strip(),
                "name": str(r.get("name") or "").strip(),
                "entrydate": _fecha_tabla_json(r.get("entrydate")),
                "ceasedate": _fecha_tabla_json(r.get("ceasedate")),
                "calculationdate": _fecha_hora_tabla_json(r.get("calculationdate")),
            }
            for r in rows
            if str(r.get("person") or "").strip()
        ]
        return jsonify(trabajadores)
    except Exception as e:
        logging.exception("api_procesar_planilla_trabajadores")
        return jsonify({"error": str(e)}), 500
    finally:
        if conn:
            try:
                conn.close()
            except Exception:
                pass


