@app.route('/api/procesar-planilla/resumen-calculo', methods=['POST'])
@login_required
def api_procesar_planilla_resumen_calculo():
    """sp_pr_resumen_calculo_web: resumen por concepto del cálculo recién procesado."""
    body = request.get_json(silent=True) or {}
    cia = str(body.get('cia') or '').strip()
    payrolltype = str(body.get('payrolltype') or body.get('payroll_type') or '').strip()
    processtype = str(body.get('processtype') or body.get('proceso') or '').strip()
    period = _normalize_pr_period(body.get('period'))
    seleccionados = body.get('trabajadores')

    if not isinstance(seleccionados, list) or len(seleccionados) == 0:
        return jsonify({'error': 'Debe indicar los trabajadores del cálculo.'}), 400
    if not cia or not payrolltype or not processtype or not period:
        return jsonify({'error': 'Faltan compañía, tipo de planilla, proceso o periodo.'}), 400

    personas = [str(x).strip() for x in seleccionados if str(x).strip()]
    if not personas:
        return jsonify({'error': 'No hay trabajadores válidos en la lista.'}), 400

    conn = None
    try:
        conn = get_db_connection()
        cursor = conn.cursor()

        proceso_desc = str(body.get('proceso_desc') or '').strip() or processtype
        planilla_desc = str(body.get('planilla_desc') or '').strip() or payrolltype

        cursor.execute(
            "SELECT TOP 1 LTRIM(RTRIM(ISNULL(Description, ''))) "
            "FROM PR_ProcessType (NOLOCK) WHERE Company = ? AND ProcessType = ?",
            (cia, processtype),
        )
        row_proc = cursor.fetchone()
        if row_proc and row_proc[0]:
            proceso_desc = str(row_proc[0]).strip()

        cursor.execute(
            "SELECT TOP 1 LTRIM(RTRIM(ISNULL(Description, ''))) "
            "FROM PR_PayRollType (NOLOCK) WHERE Company = ? AND PayRollType = ?",
            (cia, payrolltype),
        )
        row_pt = cursor.fetchone()
        if row_pt and row_pt[0]:
            planilla_desc = str(row_pt[0]).strip()

        cursor.execute(
            'EXEC sp_pr_resumen_calculo_web @cia=?, @payrolltype=?, @processtype=?, @period=?, @personas=?',
            (cia, payrolltype, processtype, period, ','.join(personas)),
        )
        rows = _dicts_first_nonempty_resultset(cursor)

        detalle = []
        total_ingresos = 0.0
        total_descuentos = 0.0
        total_auxiliar = 0.0
        total_otros = 0.0

        for r in rows:
            try:
                importe = float(r.get('importe') or 0)
            except (TypeError, ValueError):
                importe = 0.0
            tipo_codigo = str(r.get('tipo_codigo') or '').strip().upper()
            if tipo_codigo == 'I':
                total_ingresos += importe
            elif tipo_codigo == 'D':
                total_descuentos += importe
            elif tipo_codigo == 'A':
                total_auxiliar += importe
            else:
                total_otros += importe
            detalle.append(
                {
                    'concepto': str(r.get('concepto') or '').strip(),
                    'formulacode': str(r.get('formulacode') or '').strip(),
                    'tipo': str(r.get('tipo') or '').strip(),
                    'tipo_codigo': tipo_codigo,
                    'num_trabajadores': int(r.get('num_trabajadores') or 0),
                    'importe': importe,
                }
            )

        return jsonify(
            {
                'cia': cia,
                'payrolltype': payrolltype,
                'payrolltype_desc': planilla_desc,
                'processtype': processtype,
                'proceso_desc': proceso_desc,
                'period': period,
                'num_trabajadores': len(personas),
                'rows': detalle,
                'totales': {
                    'ingresos': total_ingresos,
                    'descuentos': total_descuentos,
                    'auxiliar': total_auxiliar,
                    'otros': total_otros,
                    'neto': total_ingresos - total_descuentos,
                },
            }
        )
    except Exception as e:
        logging.exception('api_procesar_planilla_resumen_calculo')
        return jsonify({'error': str(e)}), 500
    finally:
        if conn:
            try:
                conn.close()
            except Exception:
                pass


@app.route('/api/procesar-planilla/eliminar-calculo', methods=['POST'])
@login_required
def api_procesar_planilla_eliminar_calculo():
    """sp_pr_eliminar_calculo_planilla_web: elimina cálculo de trabajadores seleccionados."""
    body = request.get_json(silent=True) or {}
    cia = str(body.get('cia') or '').strip()
    payrolltype = str(body.get('payrolltype') or body.get('payroll_type') or '').strip()
    processtype = str(body.get('processtype') or body.get('proceso') or '').strip()
    period = _normalize_pr_period(body.get('period'))
    seleccionados = body.get('trabajadores')

    if not isinstance(seleccionados, list) or len(seleccionados) == 0:
        return jsonify({"error": "Debe seleccionar al menos un trabajador."}), 400
    if not cia or not payrolltype or not processtype or not period:
        return jsonify({"error": "Faltan compañía, tipo de planilla, proceso o periodo."}), 400

    conn = None
    exitos = 0
    errores = []
    try:
        conn = get_db_connection()
        cursor = conn.cursor()
        for person_id in seleccionados:
            pid = str(person_id).strip()
            if not pid:
                continue
            try:
                cursor.execute(
                    "EXEC sp_pr_eliminar_calculo_planilla_web "
                    "@company=?, @payrolltype=?, @processtype=?, @period=?, @person=?",
                    (cia, payrolltype, processtype, period, pid),
                )
                _drain_pyodbc_cursor(cursor)
                conn.commit()
                exitos += 1
            except Exception as e_individual:
                try:
                    conn.rollback()
                except Exception:
                    pass
                err = str(e_individual)
                if 'RAISERROR' in err or '50000' in err:
                    parts = err.split(']')
                    if len(parts) > 1:
                        err = parts[-1].strip(" ()'\"")
                errores.append(f'{pid}: {err}')
                logging.warning('api_procesar_planilla_eliminar_calculo persona %s: %s', pid, e_individual)

        if errores and exitos == 0:
            return jsonify({"error": '; '.join(errores), "exitos": exitos, "errores": errores}), 500
        return jsonify({
            "ok": True,
            "exitos": exitos,
            "errores": errores,
            "mensaje": "Proceso concluido." if not errores else f"Proceso concluido con {len(errores)} error(es).",
        })
    except Exception as e:
        logging.exception("api_procesar_planilla_eliminar_calculo")
        return jsonify({"error": str(e)}), 500
    finally:
        if conn:
            try:
                conn.close()
            except Exception:
                pass


@app.route('/ejecutar_calculo_planilla', methods=['POST'])
@login_required
def ejecutar_calculo_planilla():
    """
    Resuelve el SP en PR_ProcessType (ProcedureName) y lo ejecuta por cada person.
    Orden de parámetros del CALL: cia, payroll_type, processtype, period, person, user_id, tc.
    """
    ensure_user_session()
    body = request.get_json(silent=True) or {}
    cia = str(body.get('cia') or session.get('company') or '').strip()
    processtype = str(body.get('processtype') or '').strip()
    payroll_type = str(body.get('payroll_type') or '').strip()
    period = _normalize_pr_period(body.get('period'))
    seleccionados = body.get('trabajadores')

    if not isinstance(seleccionados, list) or len(seleccionados) == 0:
        return jsonify({'error': 'Debe enviar una lista no vacía de trabajadores (person).'}), 400
    if not cia or not processtype or not payroll_type or not period:
        return jsonify({'error': 'Faltan compañía, tipo de planilla, proceso o periodo.'}), 400

    try:
        user_id = current_user.id
    except AttributeError:
        return jsonify({'error': 'Usuario no identificado.'}), 401

    tc = 3.0
    conn = None
    try:
        conn = get_db_connection()
        cursor = conn.cursor()
        _set_cursor_timeout_payroll(cursor)
        sp_name, proceso_desc = _resolve_payroll_calc_procedure(cursor, cia, processtype)
        if not sp_name:
            return jsonify(
                {
                    'error': (
                        f'El proceso "{proceso_desc}" no tiene un procedimiento de cálculo '
                        f'configurado (ProcedureName).'
                    )
                }
            ), 400

        _drain_pyodbc_cursor(cursor)

        try:
            pre_validaciones = _validar_pre_calculo_planilla_mensajes(
                cursor, cia, payroll_type, processtype
            )
        except Exception:
            logging.exception('validar_pre_calculo_planilla antes de ejecutar_calculo_planilla')
            pre_validaciones = []

        if pre_validaciones:
            return jsonify(
                {
                    'error': (
                        'No se puede calcular: hay conceptos configurados en más de una vía. '
                        'Revise las validaciones previas.'
                    ),
                    'validaciones_pre': pre_validaciones,
                }
            ), 400

        exitos = 0
        errores = []
        call_sql = f'{{CALL {sp_name} (?, ?, ?, ?, ?, ?, ?)}}'

        for person_id in seleccionados:
            pid = str(person_id).strip()
            if not pid:
                continue
            try:
                cursor.execute(
                    call_sql,
                    (cia, payroll_type, processtype, period, pid, user_id, tc),
                )
                _drain_pyodbc_cursor(cursor)
                conn.commit()
                exitos += 1
            except Exception as e_individual:
                if _is_transient_sql_error(e_individual):
                    logging.warning(
                        'ejecutar_calculo_planilla persona %s: error transitorio; reintentando 1 vez',
                        pid,
                    )
                    try:
                        try:
                            conn.close()
                        except Exception:
                            pass
                        conn = get_db_connection()
                        cursor = conn.cursor()
                        _set_cursor_timeout_payroll(cursor)
                        cursor.execute(
                            call_sql,
                            (cia, payroll_type, processtype, period, pid, user_id, tc),
                        )
                        _drain_pyodbc_cursor(cursor)
                        conn.commit()
                        exitos += 1
                        continue
                    except Exception as e_retry:
                        try:
                            conn.rollback()
                        except Exception:
                            pass
                        errores.append(f'Error en {pid}: {e_retry}')
                        logging.warning(
                            'ejecutar_calculo_planilla persona %s fallo en reintento: %s',
                            pid,
                            e_retry,
                        )
                else:
                    try:
                        conn.rollback()
                    except Exception:
                        pass
                    errores.append(f'Error en {pid}: {e_individual}')
                    logging.warning('ejecutar_calculo_planilla persona %s: %s', pid, e_individual)

        validaciones = []
        if exitos > 0:
            try:
                validaciones = _validar_calculo_planilla_mensajes(
                    cursor, cia, payroll_type, processtype, period
                )
            except Exception:
                logging.exception('validar_calculo_planilla tras ejecutar_calculo_planilla')

        status = 'success' if not errores else 'partial'
        n_errores = len(errores)
        message = f'Proceso terminado. Éxitos: {exitos}, Errores: {n_errores}.'
        return jsonify(
            {
                'status': status,
                'message': message,
                'exitos': exitos,
                'errores': n_errores,
                'procesados': exitos + n_errores,
                'detalles': errores,
                'validaciones': validaciones,
            }
        )
    except Exception as e:
        logging.exception('ejecutar_calculo_planilla')
        return jsonify({'error': str(e)}), 500
    finally:
        if conn:
            try:
                conn.close()
            except Exception:
                pass


@app.route('/ejecutar_calculo_streaming', methods=['POST'])
@login_required
def ejecutar_calculo_streaming():
    """
    Mismo orquestado que /ejecutar_calculo_planilla pero emite eventos SSE (text/event-stream)
    tras cada trabajador: data: {"progreso","actual","total"} y al final data: {"done",...}.
    """
    ensure_user_session()
    body = request.get_json(silent=True) or {}
    cia = str(body.get('cia') or session.get('company') or '').strip()
    processtype = str(body.get('processtype') or '').strip()
    payroll_type = str(body.get('payroll_type') or '').strip()
    period = _normalize_pr_period(body.get('period'))
    seleccionados = body.get('trabajadores')

    if not isinstance(seleccionados, list) or len(seleccionados) == 0:
        return jsonify({'error': 'Debe enviar una lista no vacía de trabajadores (person).'}), 400
    if not cia or not processtype or not payroll_type or not period:
        return jsonify({'error': 'Faltan compañía, tipo de planilla, proceso o periodo.'}), 400

    try:
        user_id = current_user.id
    except AttributeError:
        return jsonify({'error': 'Usuario no identificado.'}), 401

    lista = [str(x).strip() for x in seleccionados if str(x).strip()]
    total = len(lista)
    if total == 0:
        return jsonify({'error': 'No hay IDs de trabajador válidos en la lista.'}), 400

    from database import get_active_database
    try:
        client_db = get_active_database(required=True)
    except ValueError as e:
        return jsonify({'error': str(e)}), 400
    tc = 3.0

    def generar_progreso():
        conn = None
        try:
            conn = get_db_connection(database=client_db)
            cursor = conn.cursor()
            _set_cursor_timeout_payroll(cursor)
            sp_name, proceso_desc = _resolve_payroll_calc_procedure(cursor, cia, processtype)
            if not sp_name:
                yield (
                    'data: '
                    + json.dumps(
                        {
                            'error': (
                                f'El proceso "{proceso_desc}" no tiene un procedimiento de cálculo '
                                f'configurado (ProcedureName).'
                            )
                        }
                    )
                    + '\n\n'
                )
                return

            _drain_pyodbc_cursor(cursor)

            try:
                pre_validaciones = _validar_pre_calculo_planilla_mensajes(
                    cursor, cia, payroll_type, processtype
                )
            except Exception:
                logging.exception('validar_pre_calculo_planilla antes de ejecutar_calculo_streaming')
                pre_validaciones = []

            if pre_validaciones:
                yield (
                    'data: '
                    + json.dumps(
                        {
                            'error': (
                                'No se puede calcular: hay conceptos configurados en más de una vía. '
                                'Revise las validaciones previas.'
                            ),
                            'validaciones_pre': pre_validaciones,
                        }
                    )
                    + '\n\n'
                )
                return

            exitos = 0
            errores = []
            call_sql = f'{{CALL {sp_name} (?, ?, ?, ?, ?, ?, ?)}}'

            for index, pid in enumerate(lista):
                try:
                    cursor.execute(
                        call_sql,
                        (cia, payroll_type, processtype, period, pid, user_id, tc),
                    )
                    _drain_pyodbc_cursor(cursor)
                    conn.commit()
                    exitos += 1
                    evento = {
                        'progreso': int(((index + 1) / total) * 100),
                        'actual': index + 1,
                        'total': total,
                        'person': pid,
                    }
                except Exception as e_individual:
                    if _is_transient_sql_error(e_individual):
                        logging.warning(
                            'ejecutar_calculo_streaming persona %s: error transitorio; reintentando 1 vez',
                            pid,
                        )
                        try:
                            try:
                                conn.close()
                            except Exception:
                                pass
                            conn = get_db_connection(database=client_db)
                            cursor = conn.cursor()
                            _set_cursor_timeout_payroll(cursor)
                            cursor.execute(
                                call_sql,
                                (cia, payroll_type, processtype, period, pid, user_id, tc),
                            )
                            _drain_pyodbc_cursor(cursor)
                            conn.commit()
                            exitos += 1
                            evento = {
                                'progreso': int(((index + 1) / total) * 100),
                                'actual': index + 1,
                                'total': total,
                            }
                        except Exception as e_retry:
                            try:
                                conn.rollback()
                            except Exception:
                                pass
                            msg = str(e_retry)
                            errores.append(f'Error en {pid}: {msg}')
                            logging.warning(
                                'ejecutar_calculo_streaming persona %s fallo en reintento: %s',
                                pid,
                                e_retry,
                            )
                            evento = {
                                'progreso': int(((index + 1) / total) * 100),
                                'actual': index + 1,
                                'total': total,
                                'detalle': msg,
                                'person': pid,
                            }
                    else:
                        try:
                            conn.rollback()
                        except Exception:
                            pass
                        msg = str(e_individual)
                        errores.append(f'Error en {pid}: {msg}')
                        logging.warning('ejecutar_calculo_streaming persona %s: %s', pid, e_individual)
                        evento = {
                            'progreso': int(((index + 1) / total) * 100),
                            'actual': index + 1,
                            'total': total,
                            'detalle': msg,
                            'person': pid,
                        }

                yield f'data: {json.dumps(evento)}\n\n'

            validaciones = []
            if exitos > 0:
                try:
                    validaciones = _validar_calculo_planilla_mensajes(
                        cursor, cia, payroll_type, processtype, period
                    )
                except Exception:
                    logging.exception('validar_calculo_planilla tras ejecutar_calculo_streaming')

            yield (
                'data: '
                + json.dumps(
                    {
                        'done': True,
                        'exitos': exitos,
                        'errores': len(errores),
                        'detalles': errores,
                        'validaciones': validaciones,
                        'database': client_db,
                    }
                )
                + '\n\n'
            )
        except Exception as e:
            logging.exception('ejecutar_calculo_streaming')
            yield f'data: {json.dumps({"error": str(e)})}\n\n'
        finally:
            if conn:
                try:
                    conn.close()
                except Exception:
                    pass

    return Response(
        stream_with_context(generar_progreso()),
        mimetype='text/event-stream',
        headers={
            'Cache-Control': 'no-cache',
            'Connection': 'keep-alive',
            'X-Accel-Buffering': 'no',
        },
    )


# ==========================================
# Comparar planillas (BD actual vs referencia)
# ==========================================

_COMPARE_PLANILLA_CACHE = {}
_COMPARE_PLANILLA_LOCK = threading.Lock()
_COMPARE_PLANILLA_TTL_SEC = 3600
_COMPARE_AMOUNT_EPS = 0.009  # tolerancia centavos


def _sanitize_sql_database_name(name):
    """Solo letras, números y underscore (nombre de BD ODBC)."""
    raw = str(name or '').strip()
    if not raw or not re.fullmatch(r'[A-Za-z0-9_]+', raw):
        return ''
    if len(raw) > 64:
        return ''
    return raw


def _compare_cache_put(payload):
    compare_id = uuid.uuid4().hex
    now = time.time()
    with _COMPARE_PLANILLA_LOCK:
        stale = [
            k for k, v in _COMPARE_PLANILLA_CACHE.items()
            if now - float(v.get('created_at') or 0) > _COMPARE_PLANILLA_TTL_SEC
        ]
        for k in stale:
            _COMPARE_PLANILLA_CACHE.pop(k, None)
        _COMPARE_PLANILLA_CACHE[compare_id] = {
            'created_at': now,
            **payload,
        }
    return compare_id


def _compare_cache_get(compare_id):
    compare_id = str(compare_id or '').strip()
    if not compare_id:
        return None
    with _COMPARE_PLANILLA_LOCK:
        item = _COMPARE_PLANILLA_CACHE.get(compare_id)
        if not item:
            return None
        if time.time() - float(item.get('created_at') or 0) > _COMPARE_PLANILLA_TTL_SEC:
            _COMPARE_PLANILLA_CACHE.pop(compare_id, None)
            return None
        return item


def _float_concept_amount(row):
    for key in ('importe', 'ConceptValueLo', 'conceptvaluelo', 'ConceptValue', 'conceptvalue'):
        if key in row and row.get(key) is not None:
            try:
                return float(row.get(key))
            except (TypeError, ValueError):
                pass
    return 0.0


def _fetch_formulacodes_tipo_shortname(conn, cia, shortnames):
    """FormulaCodes de la cia cuyo PR_ConceptType.ShortName está en shortnames (ej. X=Auxiliares)."""
    names = [
        str(s or '').strip().upper()
        for s in (shortnames or [])
        if str(s or '').strip()
    ]
    if not names:
        return set()
    ph = ','.join('?' for _ in names)
    cur = conn.cursor()
    cur.execute(
        f"""
        SELECT DISTINCT UPPER(LTRIM(RTRIM(ISNULL(C.FormulaCode, ''))))
        FROM PR_Concept C WITH (NOLOCK)
            INNER JOIN PR_ConceptType CT WITH (NOLOCK)
                ON CT.ConceptType = C.ConceptType
        WHERE C.Company = ?
          AND UPPER(LTRIM(RTRIM(ISNULL(CT.ShortName, '')))) IN ({ph})
          AND LTRIM(RTRIM(ISNULL(C.FormulaCode, ''))) <> ''
        """,
        [cia, *names],
    )
    out = set()
    for (fc,) in cur.fetchall():
        fc = str(fc or '').strip().upper()
        if fc:
            out.add(fc)
    return out


def _filtrar_map_por_formulacodes_excluidos(concept_map, excluidos):
    if not excluidos:
        return concept_map
    return {
        k: v
        for k, v in concept_map.items()
        if str((v or {}).get('formulacode') or '').strip().upper() not in excluidos
    }


def _fetch_payroll_concepts_map(conn, cia, payroll_type, processtype, period, persons):
    """
    Devuelve dict[(person, concept)] = {importe, description, formulacode, nombre}.
    Solo: tipos I/D/A (ingreso/descuento/aporte vía PR_ConceptType.ShortName) o FormulaCode
    TOTALINGRESO, TOTALEGRESOS, TOTALPATRONAL, NETO. Excluye auxiliares (X) y demás tipos.
    Consulta simple con IN (sin temp tables / hilos / fast_executemany).
    """
    if not persons:
        return {}

    chunks = [persons[i:i + 80] for i in range(0, len(persons), 80)]
    out = {}
    names = {}
    cur = conn.cursor()

    for chunk in chunks:
        ph = ','.join('?' for _ in chunk)
        cur.execute(
            f"""
            SELECT
                Person,
                LTRIM(RTRIM(ISNULL(LastName1, ''))) + ' ' +
                LTRIM(RTRIM(ISNULL(LastName2, ''))) + ' ' +
                LTRIM(RTRIM(ISNULL(Name1, ''))) + ' ' +
                LTRIM(RTRIM(ISNULL(Name2, ''))) AS nombre
            FROM SY_Person
            WHERE Person IN ({ph})
            """,
            chunk,
        )
        for r in cur.fetchall():
            if r and r[0]:
                names[str(r[0]).strip()] = str(r[1] or '').strip()

        cur.execute(
            f"""
            SELECT
                E.Person,
                E.Concept,
                ISNULL(C.Description, E.Concept) AS description,
                ISNULL(C.FormulaCode, '') AS formulacode,
                CAST(ISNULL(E.ConceptValueLo, E.ConceptValue) AS FLOAT) AS importe
            FROM PR_EmployeePayRollConcept E WITH (NOLOCK)
                INNER JOIN PR_Concept C WITH (NOLOCK)
                    ON C.Company = E.Company AND C.Concept = E.Concept
                INNER JOIN PR_ConceptType CT WITH (NOLOCK)
                    ON CT.ConceptType = C.ConceptType
            WHERE E.Company = ?
              AND E.PayRollType = ?
              AND E.ProcessType = ?
              AND E.PRPeriod = ?
              AND E.Person IN ({ph})
              AND UPPER(LTRIM(RTRIM(ISNULL(CT.ShortName, '')))) <> 'X'
              AND (
                    UPPER(LTRIM(RTRIM(ISNULL(CT.ShortName, '')))) IN ('I', 'D', 'A')
                 OR UPPER(LTRIM(RTRIM(ISNULL(C.FormulaCode, '')))) IN (
                        'TOTALINGRESO', 'TOTALEGRESOS', 'TOTALPATRONAL', 'NETO'
                    )
              )
            """,
            [cia, payroll_type, processtype, period, *chunk],
        )
        for person_raw, concept_raw, description, formulacode, importe in cur.fetchall():
            person = str(person_raw or '').strip()
            concept = str(concept_raw or '').strip()
            if not person or not concept:
                continue
            try:
                imp = float(importe or 0)
            except (TypeError, ValueError):
                imp = 0.0
            out[(person, concept)] = {
                'person': person,
                'concept': concept,
                'description': str(description or concept).strip(),
                'formulacode': str(formulacode or '').strip(),
                'importe': imp,
                'nombre': names.get(person, ''),
            }
    return out


def _comparar_planillas_conceptos(map_actual, map_ref):
    """Solo diferencias de importe. Concepto = Description (nombre), nunca FormulaCode."""
    keys = set(map_actual.keys()) | set(map_ref.keys())
    diffs = []
    for key in sorted(keys, key=lambda k: (k[0], k[1])):
        a = map_actual.get(key)
        b = map_ref.get(key)
        imp_a = float(a['importe']) if a else 0.0
        imp_b = float(b['importe']) if b else 0.0
        if abs(imp_a - imp_b) <= _COMPARE_AMOUNT_EPS:
            continue
        person = key[0]
        nombre = (a or b or {}).get('nombre') or ''
        # Nombre descriptivo (Description), nunca FormulaCode/nemónico.
        desc_a = str((a or {}).get('description') or '').strip()
        desc_b = str((b or {}).get('description') or '').strip()
        nombre_concepto = desc_a or desc_b or key[1]
        diffs.append({
            'person': person,
            'nombre': nombre,
            'concept': key[1],
            'formulacode': (a or b or {}).get('formulacode') or '',
            'concepto_actual': desc_a or nombre_concepto,
            'importe_actual': round(imp_a, 4),
            'concepto_referencia': desc_b or nombre_concepto,
            'importe_referencia': round(imp_b, 4),
            'diferencia': round(imp_a - imp_b, 4),
            'solo_actual': a is not None and b is None,
            'solo_referencia': a is None and b is not None,
        })
    return diffs


def _fetch_concepts_pair(db_actual, db_ref, cia, payroll_type, processtype, period, persons):
    """
    Lee ambas BD en secuencia.
    Si un FormulaCode es Auxiliar (PR_ConceptType.ShortName=X) en alguna BD,
    se excluye de ambas (evita falsos diffs cuando en referencia está mal tipado como I).
    """
    map_act = {}
    map_ref = {}
    aux_fc = set()
    conn_act = None
    conn_ref = None
    try:
        conn_act = get_db_connection(database=db_actual)
        map_act = _fetch_payroll_concepts_map(
            conn_act, cia, payroll_type, processtype, period, persons
        )
        aux_fc |= _fetch_formulacodes_tipo_shortname(conn_act, cia, ['X'])
    finally:
        if conn_act:
            try:
                conn_act.close()
            except Exception:
                pass
    try:
        conn_ref = get_db_connection(database=db_ref)
        map_ref = _fetch_payroll_concepts_map(
            conn_ref, cia, payroll_type, processtype, period, persons
        )
        aux_fc |= _fetch_formulacodes_tipo_shortname(conn_ref, cia, ['X'])
    finally:
        if conn_ref:
            try:
                conn_ref.close()
            except Exception:
                pass
    if aux_fc:
        map_act = _filtrar_map_por_formulacodes_excluidos(map_act, aux_fc)
        map_ref = _filtrar_map_por_formulacodes_excluidos(map_ref, aux_fc)
    return map_act, map_ref


@app.route('/ejecutar_comparar_planilla_streaming', methods=['POST'])
@login_required
def ejecutar_comparar_planilla_streaming():
    """
    1) Calcula planilla en BD actual (mismo SP que Procesar planilla).
    2) Compara PR_EmployeePayRollConcept (e existencia en PR_EmployeePayRoll)
       contra la BD de referencia.
    """
    ensure_user_session()
    body = request.get_json(silent=True) or {}
    cia = str(body.get('cia') or session.get('company') or '').strip()
    processtype = str(body.get('processtype') or '').strip()
    payroll_type = str(body.get('payroll_type') or body.get('payrolltype') or '').strip()
    period = _normalize_pr_period(body.get('period'))
    bd_ref = _sanitize_sql_database_name(body.get('bd_referencia') or body.get('bd_ref') or '')
    seleccionados = body.get('trabajadores') or []

    if not isinstance(seleccionados, list) or not seleccionados:
        return jsonify({'error': 'Debe enviar una lista no vacía de trabajadores.'}), 400
    if not cia or not processtype or not payroll_type or not period:
        return jsonify({'error': 'Faltan compañía, tipo de planilla, proceso o periodo.'}), 400
    if not bd_ref:
        return jsonify({'error': 'BD referencia inválida. Use solo letras, números y _ (ej. hm_aci).'}), 400

    try:
        user_id = current_user.id
    except AttributeError:
        return jsonify({'error': 'Usuario no identificado.'}), 401

    lista = [str(x).strip() for x in seleccionados if str(x).strip()]
    total = len(lista)
    if total == 0:
        return jsonify({'error': 'No hay IDs de trabajador válidos.'}), 400

    from database import get_active_database
    try:
        client_db = get_active_database(required=True)
    except ValueError as e:
        return jsonify({'error': str(e)}), 400

    if client_db.strip().lower() == bd_ref.lower():
        return jsonify({'error': 'La BD referencia no puede ser igual a la BD actual.'}), 400

    # Verifica que la BD referencia exista / sea reachable
    try:
        conn_probe = get_db_connection(database=bd_ref)
        conn_probe.close()
    except Exception as e:
        return jsonify({'error': f'No se pudo conectar a BD referencia "{bd_ref}": {e}'}), 400

    tc = 3.0

    def generar():
        conn = None
        try:
            conn = get_db_connection(database=client_db)
            cursor = conn.cursor()
            _set_cursor_timeout_payroll(cursor)
            sp_name, proceso_desc = _resolve_payroll_calc_procedure(cursor, cia, processtype)
            if not sp_name:
                yield (
                    'data: '
                    + json.dumps(
                        {
                            'error': (
                                f'El proceso "{proceso_desc}" no tiene procedimiento de cálculo '
                                f'(ProcedureName).'
                            )
                        }
                    )
                    + '\n\n'
                )
                return

            _drain_pyodbc_cursor(cursor)
            try:
                pre_validaciones = _validar_pre_calculo_planilla_mensajes(
                    cursor, cia, payroll_type, processtype
                )
            except Exception:
                logging.exception('comparar_planilla pre-validacion')
                pre_validaciones = []
            if pre_validaciones:
                yield (
                    'data: '
                    + json.dumps(
                        {
                            'error': 'No se puede calcular: hay validaciones previas.',
                            'validaciones_pre': pre_validaciones,
                        }
                    )
                    + '\n\n'
                )
                return

            exitos = 0
            errores = []
            call_sql = f'{{CALL {sp_name} (?, ?, ?, ?, ?, ?, ?)}}'
            for index, pid in enumerate(lista):
                try:
                    cursor.execute(
                        call_sql,
                        (cia, payroll_type, processtype, period, pid, user_id, tc),
                    )
                    _drain_pyodbc_cursor(cursor)
                    conn.commit()
                    exitos += 1
                    yield (
                        'data: '
                        + json.dumps(
                            {
                                'progreso': int(((index + 1) / total) * 100),
                                'actual': index + 1,
                                'total': total,
                                'fase': 'calculando',
                            }
                        )
                        + '\n\n'
                    )
                except Exception as e_individual:
                    conn.rollback()
                    errores.append({'person': pid, 'error': str(e_individual)})
                    logging.warning(
                        'comparar_planilla calc persona %s: %s', pid, e_individual
                    )
                    yield (
                        'data: '
                        + json.dumps(
                            {
                                'progreso': int(((index + 1) / total) * 100),
                                'actual': index + 1,
                                'total': total,
                                'fase': 'calculando',
                                'detalle': f'{pid}: {e_individual}',
                            }
                        )
                        + '\n\n'
                    )

            yield 'data: ' + json.dumps({'fase': 'comparando', 'actual': total, 'total': total}) + '\n\n'

            # Cierra conexión de cálculo antes de comparar (libera locks / pool).
            try:
                conn.close()
            except Exception:
                pass
            conn = None

            t0 = time.time()
            logging.info(
                'comparar_planilla: inicio lectura conceptos act=%s ref=%s personas=%s',
                client_db, bd_ref, len(lista),
            )
            map_act, map_ref = _fetch_concepts_pair(
                client_db, bd_ref, cia, payroll_type, processtype, period, lista
            )
            diffs = _comparar_planillas_conceptos(map_act, map_ref)
            elapsed_cmp = round(time.time() - t0, 2)
            logging.info(
                'comparar_planilla: fin comparación en %ss (act=%s ref=%s diffs=%s)',
                elapsed_cmp, len(map_act), len(map_ref), len(diffs),
            )

            compare_id = _compare_cache_put(
                {
                    'meta': {
                        'bd_actual': client_db,
                        'bd_referencia': bd_ref,
                        'cia': cia,
                        'payroll_type': payroll_type,
                        'processtype': processtype,
                        'period': period,
                        'num_trabajadores': total,
                        'exitos': exitos,
                        'errores_calculo': len(errores),
                        'segundos_comparacion': elapsed_cmp,
                        'filas_actual': len(map_act),
                        'filas_referencia': len(map_ref),
                    },
                    'diferencias': diffs,
                    'user_id': str(user_id),
                }
            )

            yield (
                'data: '
                + json.dumps(
                    {
                        'done': True,
                        'compare_id': compare_id,
                        'exitos': exitos,
                        'errores_calculo': len(errores),
                        'diferencias': len(diffs),
                        'bd_actual': client_db,
                        'bd_referencia': bd_ref,
                        'segundos_comparacion': elapsed_cmp,
                    }
                )
                + '\n\n'
            )
        except Exception as e:
            logging.exception('ejecutar_comparar_planilla_streaming')
            yield f'data: {json.dumps({"error": str(e)})}\n\n'
        finally:
            if conn:
                try:
                    conn.close()
                except Exception:
                    pass

    return Response(
        stream_with_context(generar()),
        mimetype='text/event-stream',
        headers={
            'Cache-Control': 'no-cache',
            'Connection': 'keep-alive',
            'X-Accel-Buffering': 'no',
        },
    )


@app.route('/api/comparar-planillas/resultado')
@login_required
def api_comparar_planillas_resultado():
    compare_id = str(request.args.get('id') or '').strip()
    item = _compare_cache_get(compare_id)
    if not item:
        return jsonify({'error': 'Resultado no encontrado o expirado. Vuelva a comparar.'}), 404
    return jsonify(
        {
            'meta': item.get('meta') or {},
            'diferencias': item.get('diferencias') or [],
            'total': len(item.get('diferencias') or []),
        }
    )


def _companies_csv_from_list(companies):
    if not companies:
        return ''
    if isinstance(companies, str):
        return ','.join(
            c.strip().upper()
            for c in companies.split(',')
            if c and str(c).strip()
        )
    parts = []
    for item in companies:
        if isinstance(item, dict):
            code = str(item.get('company') or item.get('cia') or '').strip().upper()
        else:
            code = str(item or '').strip().upper()
        if code and code not in parts:
            parts.append(code)
    return ','.join(parts)


